utils.remove_enemies = function ()
    game.forces["enemy"].kill_all_units()  -- Removes all biters
    game.map_settings.enemy_expansion.enabled = false  -- Stops biters from expanding
    game.map_settings.enemy_evolution.enabled = false  -- Stops biters from evolving
    local surface = game.surfaces[1]
    for _, entity in pairs(surface.find_entities_filtered({type="unit-spawner"})) do
        entity.destroy()
    end
end

local directions = {'north', 'northeast', 'east', 'southeast', 'south', 'southwest', 'west', 'northwest'}

utils.get_direction = function(from_position, to_position)
    local dx = to_position.x - from_position.x
    local dy = to_position.y - from_position.y
    local adx = math.abs(dx)
    local ady = math.abs(dy)
    local diagonal_threshold = 0.5

    -- Factorio 2.0 direction values: north=0, northeast=2, east=4, southeast=6, south=8, southwest=10, west=12, northwest=14
    if adx > ady then
        if dx > 0 then
            return (ady / adx > diagonal_threshold) and (dy > 0 and 6 or 2) or 4  -- southeast/northeast or east
        else
            return (ady / adx > diagonal_threshold) and (dy > 0 and 10 or 14) or 12  -- southwest/northwest or west
        end
    else
        if dy > 0 then
            return (adx / ady > diagonal_threshold) and (dx > 0 and 6 or 10) or 8  -- southeast/southwest or south
        else
            return (adx / ady > diagonal_threshold) and (dx > 0 and 2 or 14) or 0  -- northeast/northwest or north
        end
    end
end

utils.get_direction_with_diagonals = function(from_pos, to_pos)
    local dx = to_pos.x - from_pos.x
    local dy = to_pos.y - from_pos.y

    if dx == 0 and dy == 0 then
        return nil
    end

    -- Check for cardinal directions first
    local cardinal_margin = 0.20 --0.25
    if math.abs(dx) < cardinal_margin then
        return dy > 0 and defines.direction.south or defines.direction.north
    elseif math.abs(dy) < cardinal_margin then
        return dx > 0 and defines.direction.east or defines.direction.west
    end

    -- Handle diagonal directions
    if dx > 0 then
        return dy > 0 and defines.direction.southeast or defines.direction.northeast
    else
        return dy > 0 and defines.direction.southwest or defines.direction.northwest
    end
end


utils.get_closest_entity = function(player, position)
    local closest_distance = math.huge
    local closest_entity = nil
    local entities = player.surface.find_entities_filtered{
        position = position,
        force = "player",
        radius = 5  -- Increased from 3 to 5 to better handle large entities like 3x3 drills
    }

    for _, entity in ipairs(entities) do
        if entity.name ~= 'character' and entity.name ~= 'laser-beam' then
            local distance = ((position.x - entity.position.x) ^ 2 + (position.y - entity.position.y) ^ 2) ^ 0.5
            if distance < closest_distance then
                closest_distance = distance
                closest_entity = entity
            end
        end
    end

    return closest_entity
end

utils.calculate_movement_ticks = function(player, from_pos, to_pos)
    -- Calculate distance between points
    local dx = to_pos.x - from_pos.x
    local dy = to_pos.y - from_pos.y
    local distance = math.sqrt(dx * dx + dy * dy)

    -- Get player's walking speed (tiles per tick)
    -- Character base speed is 0.15 tiles/tick
    local walking_speed = player.character_running_speed
    if not walking_speed or walking_speed == 0 then
        walking_speed = 0.15  -- Default walking speed
    end

    -- Calculate ticks needed for movement
    return math.ceil(distance / walking_speed)
end

-- Wrapper around LuaSurface.can_place_entity that replicates all checks LuaPlayer.can_place_entity performs.
-- This allows our code to validate placement without relying on an actual LuaPlayer instance.
-- extra_params can be provided by callers to pass additional flags (e.g. fast_replace) if needed.
utils.can_place_entity = function(player, entity_name, position, direction, extra_params)
    local params = extra_params or {}
    params.name = entity_name
    params.position = position
    params.direction = direction
    params.force = player.force
    -- Use the manual build-check path so the engine applies the same rules as when a human player builds.
    params.build_check_type = defines.build_check_type.manual
    return player.surface.can_place_entity(params)
end

utils.avoid_entity = function(player_index, entity, position, direction)
    local player = storage.agent_characters[player_index]
    local player_position = player.position
    for i=0, 10 do
        local can_place = player.surface.can_place_entity{
            name = entity,
            force = "player",
            position = position,
            direction = utils.get_entity_direction(entity, direction)
        }
        if can_place then
            return true
        end
        player.teleport({player_position.x + i, player_position.y + i})
    end
    player.teleport(player_position)
    return false
end

storage.crafting_queue = {}

script.on_event(defines.events.on_tick, function(event)
  -- Iterate over the crafting queue and update the remaining ticks
  for i, task in ipairs(storage.crafting_queue) do
    task.remaining_ticks = task.remaining_ticks - 1

    -- If the crafting is finished, consume the ingredients, insert the crafted entity, and remove the task from the queue
    if task.remaining_ticks <= 0 then
      for _, ingredient in pairs(task.recipe.ingredients) do
        task.player.remove_item({name = ingredient.name, count = ingredient.amount * task.count})
      end
      task.player.insert({name = task.entity_name, count = task.count})
      table.remove(storage.crafting_queue, i)
    end
  end
end)

-- Utility function to ensure a valid character exists for a given player index
-- Call this before any operation that needs the character
-- Returns the valid character entity, or creates a new one if invalid/missing
utils.ensure_valid_character = function(player_index)
    if not storage.agent_characters then
        storage.agent_characters = {}
    end

    local char = storage.agent_characters[player_index]

    -- If character is missing or invalid, create a new one
    if not char or not char.valid then

        --if not char then
        --    error("Character not available")
        --end
        --if char.position and not char.valid then
        --    error("Character at: x="..char.position.x..", y="..char.position.y)
        --end
        --if not char.valid then
        --    error("Character not valid")
        --end

        local spawn_position = {x = 0, y = (player_index - 1) * 2}

        local new_char = game.surfaces[1].create_entity{
            name = "character",
            position = spawn_position,
            force = game.forces.player
        }

        if new_char then
            storage.agent_characters[player_index] = new_char
            return new_char
        else
            error("Failed to create agent character " .. player_index)
        end
    end

    return char
end

function dump(o)
   if type(o) == 'table' then
      local s = '{ '
      for k,v in pairs(o) do
         if type(k) ~= 'number' then k = '"'..k..'"' end
         s = s .. '['..k..'] = ' .. dump(v) .. ','
      end
      return s .. '} '
   else
      return tostring(o)
   end
end

function utils.inspect(player, radius, position)
    local surface = player.surface
    local bounding_box = {
        left_top = {x = position.x - radius, y = position.y - radius},
        right_bottom = {x = position.x + radius, y = position.y + radius}
    }

    local entities = surface.find_entities_filtered({bounding_box, force = "player"})
    local entity_data = {}

    for _, entity in ipairs(entities) do
        if entity.name ~= 'character' then
            local data = {
                name = entity.name:gsub("-", "_"),
                position = entity.position,
                direction = entity.direction,--directions[entity.direction+1],
                health = entity.health,
                force = entity.force.name,
                energy = entity.energy,
                status = entity.status,
                --crafted_items = entity.crafted_items or nil
            }

            -- Get entity contents if it has an inventory
            if entity.get_inventory(defines.inventory.chest) then
                local inventory = utils.get_contents_compat(entity.get_inventory(defines.inventory.chest))
                data.contents = inventory
            end

            data.warnings = utils.get_issues(entity)

            -- Get entity orientation if it has an orientation attribute
            if entity.type == "train-stop" or entity.type == "car" or entity.type == "locomotive" then
                data.orientation = entity.orientation
            end

            -- Get connected entities for pipes and transport belts
            if entity.type == "pipe" or entity.type == "transport-belt" then
                local path_ends = find_path_ends(entity)
                data.path_ends = {}
                for _, path_end in pairs(path_ends) do
                    local path_position = {x=path_end.position.x - player.position.x, y=path_end.position.y - player.position.y}
                    table.insert(data.path_ends, {name = path_end.name:gsub("-", "_"), position = path_position, unit_number = path_end.unit_number})
                end
            end

            table.insert(entity_data, data)
        else
            local data = {
                name = "player_character",
                position = entity.position,
                direction = directions[(entity.direction/2)+1],  -- Factorio 2.0 direction values are 0,2,4,6,8,10,12,14
            }
            table.insert(entity_data, data)
        end
    end

    -- Sort entities with path_ends by the length of path_ends in descending order
    table.sort(entity_data, function(a, b)
        if a.path_ends and b.path_ends then
            return #a.path_ends > #b.path_ends
        elseif a.path_ends then
            return true
        else
            return false
        end
    end)

    -- Remove entities that exist in the path_ends of other entities
    local visited_paths = {}
    local filtered_entity_data = {}
    for _, data in ipairs(entity_data) do
        if data.path_ends then
            local should_add = true
            for _, path_end in ipairs(data.path_ends) do
                if visited_paths[path_end.unit_number] then
                    should_add = false
                    break
                end
            end
            if should_add then
                for _, path_end in ipairs(data.path_ends) do
                    visited_paths[path_end.unit_number] = true
                end
                table.insert(filtered_entity_data, data)
            else
                data.path_ends = nil
                --table.insert(filtered_entity_data, data)
            end
        else
            table.insert(filtered_entity_data, data)
        end
    end
    entity_data = filtered_entity_data

    return entity_data
end

-- Format player inventory contents for error messages
utils.format_inventory_for_error = function(player)
    local main_inv = player.get_inventory(defines.inventory.character_main)
    if not main_inv then
        return "empty"
    end

    local contents = utils.get_contents_compat(main_inv)
    if not contents or next(contents) == nil then
        return "empty"
    end

    local items = {}
    for name, count in pairs(contents) do
        table.insert(items, name .. "=" .. count)
    end

    -- Limit to first 10 items to avoid overly long error messages
    if #items > 10 then
        local truncated = {}
        for i = 1, 10 do
            truncated[i] = items[i]
        end
        return table.concat(truncated, ", ") .. " (and " .. (#items - 10) .. " more)"
    end

    return table.concat(items, ", ")
end
end

-- ==== lib: alerts.lua ====
do
-- storage.alerts init lives in init_data (initialise.lua)

-- Define a function to check if the transport belt is blocked
local function is_transport_belt_blocked(entity)
    if entity.type == "transport-belt" then
        local line_1 = entity.get_transport_line(1)
        local line_2 = entity.get_transport_line(2)

        local direction_vector = {
            [0] = {x = 0, y = -1},   -- North
            [4] = {x = 1, y = 0},    -- East (Factorio 2.0)
            [8] = {x = 0, y = 1},    -- South (Factorio 2.0)
            [12] = {x = -1, y = 0},  -- West (Factorio 2.0)
        }

        local dx = direction_vector[entity.direction].x
        local dy = direction_vector[entity.direction].y
        local next_position = {x = entity.position.x + dx, y = entity.position.y + dy}
        local next_entities = entity.surface.find_entities_filtered {
            area = {{next_position.x - 0.5, next_position.y - 0.5}, {next_position.x + 0.5, next_position.y + 0.5}},
        }

        local has_sink = false
        for _, next_entity in ipairs(next_entities) do
            if next_entity.type == "transport-belt" or next_entity.type == "splitter" or next_entity.type == "loader" or (next_entity.type == "assembling-machine" and next_entity.get_recipe()) then
                has_sink = true
                break
            end
        end

        if not has_sink then
            -- Factorio 2.0: Use compat wrapper and check for non-empty contents
            local contents_1 = line_1 and utils.get_contents_compat(line_1) or {}
            local contents_2 = line_2 and utils.get_contents_compat(line_2) or {}
            local line_1_moving = next(contents_1) ~= nil and not line_1.can_insert_at_back()
            local line_2_moving = next(contents_2) ~= nil and not line_2.can_insert_at_back()

            if line_1_moving or line_2_moving then
                return true
            end
        end
    end
    return false
end

-- Define a function to check if an entity is full
local function is_full(entity)
    -- Map inventory types to string names
    local inventory_names = {
        [defines.inventory.rocket_silo_rocket] = "rocket",
        [defines.inventory.rocket_silo_input] = "rocket input",
        [defines.inventory.rocket_silo_output] = "rocket output",
        [defines.inventory.rocket_silo_modules] = "rocket modules",
        [defines.inventory.fuel] = "fuel source",
        [defines.inventory.burnt_result] = "burnt result",
        [defines.inventory.assembling_machine_input] = "assembling machine input",
        [defines.inventory.assembling_machine_output] = "assembling machine output",
        [defines.inventory.chest] = "chest",
        [defines.inventory.furnace_source] = "furnace source",
        [defines.inventory.furnace_result] = "furnace result",
    }

    local full_inventories = {}

    -- Iterate over all possible inventory types
    for inventory_id, inventory_name in pairs(inventory_names) do
        local inventory = entity.get_inventory(inventory_id)
        -- Check if the entity has this type of inventory and if it's full
        if inventory and #inventory > 0 then
            for i = 1, #inventory do
                -- Check if the slot is completely filled
                local stack = inventory[i]
                if not stack.valid_for_read or stack.count < stack.prototype.stack_size then  -- Slot is not completely filled
                    goto continue
                end
            end

            -- Determine a more specific message depending on the entity type
            if entity.type == "furnace" then
                if inventory_id == defines.inventory.fuel then
                    inventory_name = "furnace fuel source"
                elseif inventory_id == defines.inventory.furnace_source then
                    inventory_name = "furnace source"
                elseif inventory_id == defines.inventory.furnace_result then
                    inventory_name = "furnace result"
                end
            elseif entity.type == "assembling-machine" then
                if inventory_id == defines.inventory.assembling_machine_input then
                    inventory_name = "assembler input"
                elseif inventory_id == defines.inventory.assembling_machine_output then
                    inventory_name = "assembler output"
                end
            elseif entity.type == "rocket-silo" then
                if inventory_id == defines.inventory.rocket_silo_input then
                    inventory_name = "rocket silo input"
                elseif inventory_id == defines.inventory.rocket_silo_output then
                    inventory_name = "rocket silo output"
                elseif inventory_id == defines.inventory.rocket_silo_modules then
                    inventory_name = "rocket silo modules"
                elseif inventory_id == defines.inventory.rocket then
                    inventory_name = "rocket"
                end
            elseif entity.type == "mining-drill" then
                if inventory_id == defines.inventory.chest then
                    inventory_name = "fuel source"
                end
            elseif entity.type == "chest" then
                if inventory_id == defines.inventory.chest then
                    inventory_name = "chest storage"
                end
            end

            table.insert(full_inventories, inventory_name .. " is full")  -- Add the name of the full inventory to the list

            ::continue::
        end
    end

    return full_inventories
end

local function can_mine(entity)
    if entity.type == "mining-drill" then
        -- Check if there's no resource under the drill
        if entity.mining_target == nil then
           return false
        end
    end
    return true
end
-- Define a function to check if the entity is a burner and has fuel
local function has_fuel(entity)
    if entity.burner then
        if not entity.burner.currently_burning then
            local fuel_inventory = entity.get_inventory(defines.inventory.fuel)
            local contents = utils.get_contents_compat(fuel_inventory)
            for item_name, item_count in pairs(contents) do
                local fuel_value = prototypes.item[item_name].fuel_value
                if fuel_value and fuel_value > 0 then
                    return true
                end
            end
            return false
        else
            return true
        end
    end
    return true
end

-- Define a function to check if the entity (furnace) has ingredients
local function has_ingredients(entity)
    if entity.type == "furnace" and entity.get_recipe() == nil then
        return false
    end
    return true
end

local function has_output_space(entity)
    if entity.status == defines.entity_status.waiting_for_space_in_destination then
        return false
    end
    if entity.type == "mining-drill" and entity.mining_target then
        local output_inventory = entity.get_output_inventory()
        if output_inventory and output_inventory.is_full() then
            return false
        end

        local drop_position = entity.drop_position
        local items_on_ground = entity.surface.find_entities_filtered{
            area = {{drop_position.x - 0.5, drop_position.y - 0.5}, {drop_position.x + 0.5, drop_position.y + 0.5}},
            type = "item-entity"
        }

        local destination_entity = entity.surface.find_entities_filtered{
            position = drop_position,
            type = {"container", "transport-belt", "underground-belt", "splitter"}
        }[1]

        if #items_on_ground >= 1 then
            return false
        elseif destination_entity then
            if destination_entity.type == "container" then
                local chest_inventory = destination_entity.get_inventory(defines.inventory.chest)
                return not chest_inventory.is_full()
            else
                -- For belts, undergrounds, and splitters, assume there's space
                return true
            end
        else
            -- No destination entity, check if output inventory is not empty and can't insert more
            local resource = entity.mining_target
            return not (output_inventory and not output_inventory.is_empty() and
                        output_inventory.can_insert({name = resource.name, count = 1}) == false)
        end
    end
    return true
end

local function has_electricity(entity)
    if entity.prototype.electric_energy_source_prototype then
        -- Check if the entity is connected to an electric network
        if entity.electric_network_id then
            -- Check if the entity is receiving power
            local energy_usage = entity.energy / entity.electric_buffer_size
            return energy_usage > 0
        else
            -- Entity is not connected to an electric network
            return false
        end
    end
    -- Entity doesn't require electricity
    return true
end

-- Define a function to check if the entity (boiler) has necessary input liquid
local function has_input_liquid(entity)
    if entity.type == "boiler" then
        local fluid_box = entity.fluidbox[1]
        if fluid_box == nil or fluid_box.amount <= 0 then
            return false
        end
    end
    -- If the entity is a steam engine, check if it has water
    if entity.type == "generator" then
        local fluid_box = entity.fluidbox[1]
        if fluid_box == nil or fluid_box.amount <= 0 then
            return false
        end
    end
    return true
end

local function is_inserter_waiting_for_source(entity)
    if entity.type == "inserter" then
        local pickup_target = entity.pickup_target
        if pickup_target and pickup_target.valid then
            local pickup_inventory = pickup_target.get_inventory(defines.inventory.chest)
            if pickup_inventory and pickup_inventory.is_empty() then
                return true
            end
        end
    end
    return false
end


function utils.get_issues(entity)
    local issues = {}

    if not can_mine(entity) then
        table.insert(issues, "\'nothing to mine\'")
    end
    if not has_fuel(entity) then
        table.insert(issues, "\'out of fuel\'")
    end
    if not has_ingredients(entity) then
        table.insert(issues, "\'no ingredients to smelt\'")
    end
    if is_inserter_waiting_for_source(entity) then
        table.insert(issues, "\'inserter waiting for source items\'")
    end

    local full_inventories = is_full(entity)
    for _, full_inventory in ipairs(full_inventories) do
        table.insert(issues, "\'"..full_inventory.."\'")
    end

    --if not has_output_space(entity) then
    --    if entity.drop_position ~= nil then
    --        local rounded_x = round_to_half(entity.drop_position.x)
    --        local rounded_y = round_to_half(entity.drop_position.y)
    --
    --        table.insert(issues, "\'waiting for space in destination as the output is full. Place a sink object at (" .. entity.drop_position.x .. ", ".. entity.drop_position.y .. ") to unblock.\'")
    --    else
    --        table.insert(issues, "\'waiting for space in destination\'")
    --    end
    --end
    if not has_output_space(entity) then
        if entity.drop_position then
            local rounded_x = round_to_half(entity.drop_position.x)
            local rounded_y = round_to_half(entity.drop_position.y)

            local destination_entity = entity.surface.find_entities_filtered{
                position = entity.drop_position,
                type = {"container", "transport-belt", "underground-belt", "splitter", "furnace"}
            }[1]

            if destination_entity then
                if destination_entity.type == "container" then
                    table.insert(issues, "\'chest at drop position is full. Empty the chest at (" .. rounded_x .. ", " .. rounded_y .. ") to continue mining.\'")
                elseif destination_entity.type == "furnace" then
                    table.insert(issues, "\'furnace at drop position is blocked.\'")
                else
                    table.insert(issues, "\'transport belt at drop position is blocked. Clear the belt at (" .. rounded_x .. ", " .. rounded_y .. ") to continue mining.\'")
                end
            else
                table.insert(issues, "\'output blocked by item on the ground. There is no sink entity in place to accept the output.\'")
            end
        else
            table.insert(issues, "\'waiting for space in destination\'")
        end
    end

    if not has_electricity(entity) then
        if entity.electric_network_id and (entity.type ~= 'solar-panel' and entity.type ~= 'generator') then
            table.insert(issues, "\'not receiving electricity\'")
        else
            table.insert(issues, "\'not connected to power network\'")
        end
    end

    local assembler_issue = lacks_assembler_resources(entity)
    if assembler_issue then
        table.insert(issues, assembler_issue)
    end

    if is_transport_belt_blocked(entity) then
        table.insert(issues, "\'transport belt blocked. Place an inserter to drain entities from it.\'")
    end

    if not has_input_liquid(entity) then
        table.insert(issues, "\'no input liquid\'")
    end
    return issues
end
function is_not_fluid(name)
    local items = { "crude-oil", "petroleum-gas", "sulfuric-acid", "water", "steam", "light-oil", "heavy-oil", "lubricant" }
    for _,v in pairs(items) do
      if v == name then
        return false
      end
    end
    return true
end
-- Define a function to check if the entity is an assembler machine and lacks resources
function lacks_assembler_resources(entity)
    if entity.type == "assembling-machine" then
        local recipe = entity.get_recipe()
        if recipe then
            local ingredients = recipe.ingredients
            local input_inventory = entity.get_inventory(defines.inventory.assembling_machine_input)
            local missing_resources = {}

            for _, ingredient in pairs(ingredients) do
                -- don't perform a check in the case of liquids like crude-oil, water etc.
                if is_not_fluid(ingredient.name) then
                    if prototypes.item[ingredient.name].type ~= "fluid" then
                        local available_amount = input_inventory.get_item_count(ingredient.name)
                        local missing_amount = ingredient.amount - available_amount
                        if missing_amount > 0 then
                            table.insert(missing_resources, ingredient.name .. " (" .. tostring(missing_amount) .. ")")
                        end
                    end
                end
            end

            if #missing_resources > 0 then
                return "\'cannot create " .. recipe.name .. " due to missing resources: " .. table.concat(missing_resources, ",_").."\'"

            end
        end
    end
    return false
end

-- Define a helper function to round a number to the nearest 0.5
function round_to_half(number)
    return math.floor(number * 2 + 0.5) / 2
end


-- Define a function to be called every tick
local function on_tick(event)
    -- Run the check every 60 ticks (1 second)
    if event.tick % 60 == 0 then
        for _, surface in pairs(game.surfaces) do
            local entities = surface.find_entities_filtered({force = "player"})
            for _, entity in pairs(entities) do
                local issues = utils.get_issues(entity)

                if #issues > 0 then
                    local position = entity.position
                    local entity_key = entity.name .. "_" .. position.x .. "_" .. position.y
                    local name = '"'..entity.name:gsub(" ", "_")..'"'
                    if not storage.alerts[entity_key] then
                        storage.alerts[entity_key] = {
                            position = position,
                            issues = issues,
                            entity_name = name,
                            tick = event.tick
                        }
                    end
                end
            end
        end
    end
end

-- Define a function to get alerts older than the number of seconds
get_alerts = function(seconds)
    local current_tick = game.tick
    local old_alerts = {}

    for key, alert in pairs(storage.alerts) do
        if current_tick - alert.tick > 60*seconds then
            table.insert(old_alerts, alert)
            storage.alerts[key] = nil
        end
    end

    return old_alerts
end

-- Register the on_tick function to the on_tick event
script.on_event(defines.events.on_tick, on_tick)
end

-- ==== lib: connection_points.lua ====
do
-- This is primarily used to get the connection points of entities for the purpose of blocking them during pathing.
-- This is to prevent bad cases where connections are blocked by belts / pipes etc.

-- Function to get connection points for storage tanks based on their direction
utils.get_storage_tank_connection_points = function(entity)
    local x, y = entity.position.x, entity.position.y
    local connection_points = {}

    -- Storage tanks have two possible orientations:
    -- 1. TopRight/BottomLeft connections (direction = 0 or direction = 2)
    -- 2. TopLeft/BottomRight connections (direction = 1 or direction = 3)

    -- Note: entity.direction is in Factorio's 16-way direction system (0-14)
    -- We need to handle both orientations (east/south and north/west)
    -- Factorio 2.0: north=0, east=4, south=8, west=12
    if entity.direction == defines.direction.east or entity.direction == defines.direction.south then
        -- TopRight/BottomLeft connections
        table.insert(connection_points, {x = x + 1, y = y - 2})  -- Top right - Top
        table.insert(connection_points, {x = x + 2, y = y - 1})  -- Top right - Right

        table.insert(connection_points, {x = x - 1, y = y + 2})  -- Bottom left - Bottom
        table.insert(connection_points, {x = x - 2, y = y + 1})  -- Bottom left - Left
    else
        -- TopLeft/BottomRight connections
        table.insert(connection_points, {x = x - 1, y = y - 2})  -- Top left - Top
        table.insert(connection_points, {x = x - 2, y = y - 1})  -- Top left - Left

        table.insert(connection_points, {x = x + 1, y = y + 2})  -- Bottom right - Bottom
        table.insert(connection_points, {x = x + 2, y = y + 1})  -- Bottom right - Right

    end

    return connection_points
end

utils.get_chemical_plant_connection_points = function(plant)
    local positions = {}
    local x, y = plant.position.x, plant.position.y

    if plant.direction == defines.direction.north then
        -- Input pipes
        table.insert(positions, {x = x - 1, y = y + 1.5})
        table.insert(positions, {x = x + 1, y = y + 1.5})
        -- Output pipes
        table.insert(positions, {x = x - 1, y = y - 1.5})
        table.insert(positions, {x = x + 1, y = y - 1.5})
    elseif plant.direction == defines.direction.south then
        -- Input pipes
        table.insert(positions, {x = x - 1, y = y - 1.5})
        table.insert(positions, {x = x + 1, y = y - 1.5})
        -- Output pipes
        table.insert(positions, {x = x - 1, y = y + 1.5})
        table.insert(positions, {x = x + 1, y = y + 1.5})
    elseif plant.direction == defines.direction.east then
        -- Input pipes
        table.insert(positions, {x = x - 1.5, y = y - 1})
        table.insert(positions, {x = x - 1.5, y = y + 1})
        -- Output pipes
        table.insert(positions, {x = x + 1.5, y = y - 1})
        table.insert(positions, {x = x + 1.5, y = y + 1})
    elseif plant.direction == defines.direction.west then
        -- Input pipes
        table.insert(positions, {x = x + 1.5, y = y - 1})
        table.insert(positions, {x = x + 1.5, y = y + 1})
        -- Output pipes
        table.insert(positions, {x = x - 1.5, y = y - 1})
        table.insert(positions, {x = x - 1.5, y = y + 1})
    end

    return positions
end


utils.get_generator_connection_positions = function(entity)
    local x, y = entity.position.x, entity.position.y
    local orientation = entity.orientation
    local entity_prototype = prototypes.entity[entity.name]
    local dx, dy = 0, 0
    local offsetx, offsety = 0, 0
    if orientation == 0 or orientation == defines.direction.north then
        dx, dy = 0, -1
        --offsetx, offsety = 0, 0
    elseif orientation == 0.25 or orientation == defines.direction.east then
        dx, dy = 1, 0
        --offsetx, offsety = -0.5, 0
    elseif orientation == 0.5 or orientation == defines.direction.south then
        dx, dy = 0, -1
        --offsetx, offsety = 0, -0.5
    elseif orientation == 0.75 or orientation == defines.direction.west then
        dx, dy = 1, 0
        --offsetx, offsety = 0, 0
    else
        -- Log detailed information about the unexpected orientation
        local orientation_info = string.format(
            "Numeric value: %s, Type: %s, Defines values: N=%s, E=%s, S=%s, W=%s",
            tostring(orientation),
            type(orientation),
            tostring(defines.direction.north),
            tostring(defines.direction.east),
            tostring(defines.direction.south),
            tostring(defines.direction.west)
        )
        error(string.format(
            "Unexpected orientation for entity: %s at position: %s. Orientation info: %s",
            entity.name,
            serpent.line(entity.position),
            orientation_info
        ))
    end
    local height = entity_prototype.tile_height/2
    local pipe_positions = {
        {x = x + (height*dx) + offsetx, y = y + (height*dy) + offsety},
        {x = x - (height*dx) + offsetx, y = y - (height*dy) + offsety}
    }

    return pipe_positions
end

utils.get_pumpjack_connection_points = function(entity)
    local x, y = entity.position.x, entity.position.y
    local orientation = entity.orientation

    local dx, dy
    if orientation == 0 or orientation == defines.direction.north then
        dx, dy = 1, -2
    elseif orientation == 0.25 or orientation == defines.direction.east then
        dx, dy = 2, -1
    elseif orientation == 0.5 or orientation == defines.direction.south then
        dx, dy = -1, 2
    elseif orientation == 0.75 or orientation == defines.direction.west then
        dx, dy = -2, 1
    end

    local pipe_position = {{x = x + dx, y = y + dy}}

    return pipe_position
end

utils.get_boiler_connection_points = function(entity)
    local x, y = entity.position.x, entity.position.y
    -- Factorio 2.0: orientation is 0, 0.25, 0.5, 0.75 for cardinals
    -- defines.direction values are 0, 4, 8, 12 (16-direction system)
    local orientation = entity.orientation * 16

    local dx, dy = 0, 0
    if orientation == defines.direction.north then
        dx, dy = 1.5, 0.5
