-- ==== action: get_entity ====
do
actions.get_entity = function(player_index, entity, x, y)
    -- Ensure we have a valid character, recreating if necessary
    local player = utils.ensure_valid_character(player_index)
    local position = {x=x, y=y}

    if prototypes.entity[entity] == nil then
        local name = entity:gsub(" ", "_"):gsub("-", "_")
        error(name .. " isnt something that exists. Did you make a typo? ")
    end

    local prototype = prototypes.entity[entity]
    --local collision_box = prototype.collision_box
    local width = 1--math.abs(collision_box.right_bottom.x - collision_box.left_top.x)
    local height = 1--math.abs(collision_box.right_bottom.y - collision_box.left_top.y)

    -- game.print("Width: " .. width)
    -- game.print("Height: " .. height)

    local target_area = {
        {position.x - width , position.y - height },
        {position.x + width , position.y + height }
    }
    --local entities = player.surface.find_entities_filtered{area = target_area} --, name = entity}
    local entities = player.surface.find_entities_filtered{area = target_area, name = entity}
    -- game.print("Number of entities found: " .. #entities)

    local closest_distance = math.huge
    local closest_entity = nil

    for _, building in ipairs(entities) do
        if building.name ~= 'character' then
            local distance = ((position.x - building.position.x) ^ 2 +
                            (position.y - building.position.y) ^ 2) ^ 0.5
            if distance < closest_distance then
                closest_distance = distance
                closest_entity = building
            end
        end
    end

    if closest_entity ~= nil then
        local entity = closest_entity  -- get the first entity of the specified type in the area
        local serialized = utils.serialize_entity(entity)
        --local entity_json = game.table_to_json(serialized)-- game.table_to_json(entity
        return serialized
    else
        error("\"No entity of type " .. entity .. " found at the specified position.\"")
    end
end

end

-- ==== action: get_entities ====
do
actions.get_entities = function(player_index, radius, entity_names_json, position_x, position_y)
    -- Ensure we have a valid character, recreating if necessary
    local player = utils.ensure_valid_character(player_index)

    local position
    if position_x and position_y then
        position = {x = tonumber(position_x), y = tonumber(position_y)}
    else
        position = player.position
    end

    radius = tonumber(radius) or 5
    local entity_names = helpers.json_to_table(entity_names_json) or {}
    local area = {
        {position.x - radius, position.y - radius},
        {position.x + radius, position.y + radius}
    }

    local filter = {}
    if entity_names and #entity_names > 0 then
        filter = {name = entity_names}
    end

    local entities

    if #entity_names > 0 then
        entities = player.surface.find_entities_filtered{area = area, force = player.force, filter=filter}
    else
        entities = player.surface.find_entities_filtered{area = area, force = player.force}
    end

    local result = {}
    for _, entity in ipairs(entities) do
        -- Wrap the entire entity processing in pcall to catch any LuaEntity invalid errors
        local process_success, process_error = pcall(function()
            -- Double-check validity right before accessing any properties
            if not entity.valid then
                return -- Skip silently
            end

            -- Cache the name check separately to avoid race conditions
            local entity_name = entity.name
            if entity_name == 'character' then
                return -- Skip character entities
            end

            -- Now serialize the entity
            local success, serialized = pcall(function()
                -- Final validity check before serialization
                if not entity.valid then
                    return nil
                end
                return utils.serialize_entity(entity)
            end)

            if success and serialized then
                table.insert(result, serialized)
            end
            -- Silently skip failed entities instead of printing warnings
        end)
        -- Silently continue on any error - don't let one bad entity break the whole call
    end
    return dump(result)
end
end

-- ==== action: nearest ====
do
actions.nearest = function(player_index, resource)
    -- Ensure we have a valid character, recreating if necessary
    local player = utils.ensure_valid_character(player_index)

    local function normalize_resource_name(resource)
        if resource == "copper" then
            return "copper-ore"
        elseif resource == "iron" then
            return "iron-ore"
        elseif resource == "uranium" then
            return "uranium-ore"
        else
            return resource
        end
    end

    local normalized_resource = normalize_resource_name(resource)

    local function find_nearest(player, resource)
        local surface = player.surface
        local position = player.position
        local closest_distance = math.huge
        local closest = nil
        local entities

        if resource == "wood" then
            entities = surface.find_entities_filtered{
                area = {{position.x - 500, position.y - 500}, {position.x + 500, position.y + 500}},
                type = "tree"
            }
        elseif resource == "water" then
            local water_positions = surface.find_tiles_filtered{
                area = {{position.x - 500, position.y - 500}, {position.x + 500, position.y + 500}},
                name = "water"
            }
            for _, water_tile in ipairs(water_positions) do
                local distance = ((position.x - water_tile.position.x) ^ 2 + (position.y - water_tile.position.y) ^ 2) ^ 0.5
                if distance < closest_distance then
                    closest_distance = distance
                    closest = water_tile.position
                end
            end
            if closest == nil then
                error("\"Could not find an entity called "..resource.."\"")
            end
            --return { x = position.x - closest.x, y = position.y - closest.y }
            return {x = closest.x, y = closest.y}
        else
            entities = surface.find_entities_filtered{
                area = {{position.x - 500, position.y - 500}, {position.x + 500, position.y + 500}},
                name = resource
            }
        end

        for _, entity in ipairs(entities) do
            local distance = ((position.x - entity.position.x) ^ 2 + (position.y - entity.position.y) ^ 2) ^ 0.5
            if distance < closest_distance then
                closest_distance = distance
                closest = entity.position
            end
        end

        if closest == nil then
            error("\"Could not find an entity called "..resource.."\"")
        end
        -- game.print("Distance to "..resource.." is "..closest_distance)
        return {x= closest.x, y = closest.y}
        --return { x = position.x - closest.x, y = position.y - closest.y }
    end

    return find_nearest(player, normalized_resource)
end

end

-- ==== action: place_entity ====
do
-- Helper to convert surface direction to entity direction
local function surface_to_entity_direction(surface_dir)
    -- In Factorio, offshore pumps face opposite to placement direction
    local direction_map = {
        [defines.direction.north] = defines.direction.north,  -- 0 -> 4
        [defines.direction.east] = defines.direction.east,    -- 2 -> 6
        [defines.direction.south] = defines.direction.south,  -- 4 -> 0
        [defines.direction.west] = defines.direction.west     -- 6 -> 2
    }
    return direction_map[surface_dir]
end


-- Helper to check if a tile is water
local function is_water_tile(tile_name)
    return tile_name == "water" or
           tile_name == "deepwater" or
           tile_name == "water-green" or
           tile_name == "deepwater-green" or
           tile_name == "water-shallow" or
           tile_name == "water-mud"
end

local function find_offshore_pump_position(player, center_pos)
    local max_radius = 20
    local search_positions = {
        {dx = 0, dy = 1, dir = defines.direction.north},
        {dx = 1, dy = 0, dir = defines.direction.west}, 
        {dx = 0, dy = -1, dir = defines.direction.south},
        {dx = -1, dy = 0, dir = defines.direction.east}
    }

    for radius = 1, max_radius do
        for y = -radius, radius do
            for x = -radius, radius do
                if math.abs(x) == radius or math.abs(y) == radius then
                    local check_pos = {
                        x = center_pos.x + x,
                        y = center_pos.y + y
                    }

                    -- Check if position is already occupied
                    -- Factorio 2.0: collision_mask expects a collision layer name string
                    local entities = player.surface.find_entities_filtered{
                        position = check_pos,
                        collision_mask = "player",
                        invert = false
                    }

                    if #entities == 0 then
                        local current_tile = player.surface.get_tile(check_pos.x, check_pos.y)

                        if not is_water_tile(current_tile.name) then
                            for _, search in ipairs(search_positions) do
                                local water_pos = {
                                    x = check_pos.x + search.dx,
                                    y = check_pos.y + search.dy
                                }

                                -- Check for entities at water position
                                -- Factorio 2.0: collision_mask expects a collision layer name string
                                local water_entities = player.surface.find_entities_filtered{
                                    position = water_pos,
                                    collision_mask = "water_tile",
                                    invert = true
                                }

                                if #water_entities == 0 then
                                    local adjacent_tile = player.surface.get_tile(water_pos.x, water_pos.y)

                                    if is_water_tile(adjacent_tile.name) then
                                        local entity_dir = surface_to_entity_direction(search.dir)
                                        local placement = {
                                            name = "offshore-pump",
                                            position = check_pos,
                                            direction = entity_dir,
                                            force = "player"
                                        }

                                        if player.surface.can_place_entity(placement) then
                                            -- Final collision check for the exact pump dimensions
                                            -- Factorio 2.0: collision_mask expects a collision layer name string
                                            local final_check = player.surface.find_entities_filtered{
                                                area = {{check_pos.x - 0.5, check_pos.y - 0.5},
                                                       {check_pos.x + 0.5, check_pos.y + 0.5}},
                                                collision_mask = "player"
                                            }

                                            if #final_check == 0 then
                                                return {
                                                    position = check_pos,
                                                    direction = entity_dir
                                                }
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    return nil
end

actions.place_entity = function(player_index, entity, direction, x, y, exact)
    -- Ensure we have a valid character, recreating if necessary
    local player = utils.ensure_valid_character(player_index)
    local position = {x = x, y = y}

    if not direction then
        direction = 0
    end

    local entity_direction = utils.get_entity_direction(entity, direction)

    -- Common validation functions
    local function validate_distance()
        local max_distance = player.reach_distance or player.build_distance
        local dx = player.position.x - x
        local dy = player.position.y - y or 0
        local distance = math.sqrt(dx * dx + dy * dy)

        if distance > max_distance then
            error("\"The target position is too far away to place the entity. The player position is " ..
                  player.position.x .. ", " .. player.position.y ..
                  " and the target position is " .. x .. ", " .. y ..
                  ". The distance is " .. string.format("%.2f", distance) ..
                  " and the max distance is " .. max_distance .. ". Move closer.\"")
        end
    end

    local function validate_entity()
        if prototypes.entity[entity] == nil then
            local name = entity:gsub(" ", "_"):gsub("-", "_")
            error("\""..name .. " isn't something that exists. Did you make a typo?\"")
        end
    end

    local function validate_inventory()
        local count = player.get_item_count(entity)
        if count == 0 then
            local name = entity:gsub(" ", "_"):gsub("-", "_")
            local inv_contents = utils.format_inventory_for_error(player)
            error("\"No " .. name .. " in inventory. Current inventory: " .. inv_contents .. "\"")
        end
    end

    -- Slow placement implementation
    local function slow_place()
        -- Set cursor ghost
        player.cursor_ghost = entity

        -- Select the target position
        player.update_selected_entity(position)

        -- Schedule the actual placement after delay
        script.on_nth_tick(60, function(event)  -- 30 ticks = 0.5 seconds
            script.on_nth_tick(60, nil)  -- Clear the scheduled event
 
            -- Verify conditions are still valid
            validate_distance()
            validate_inventory()

            -- Avoid entity at target position
            utils.avoid_entity(player_index, entity, position)

            -- Perform the actual placement
            local placed_entity = player.surface.create_entity{
                name = entity,
                force = "player",
                position = position,
                direction = entity_direction,
            }

            if placed_entity then
                player.remove_item{name = entity, count = 1}
                player.cursor_ghost = nil  -- Clear the ghost
                return utils.serialize_entity(placed_entity)
            else
                error("\"Failed to place entity after delay\"")
            end
        end)

        return { pending = true }
    end

    -- Fast placement implementation (existing logic)
    local function fast_place()
        local entity_prototype = prototypes.entity[entity]

        if entity == 'offshore-pump' then
            exact = false
        end

        -- Check for existing entity
        if exact then
            local existing_entity = player.surface.find_entity(entity, position)
            if existing_entity then
                error("\"entity already exists at the target position " .. serpent.line(existing_entity.position) .. " - remove this before continuing.\"" )
            end

            -- Get entity prototype's collision box
            local collision_box = entity_prototype.collision_box
            -- Calculate the area to check for water
            local check_area = {
                {position.x - collision_box.left_top.x/2, position.y - collision_box.left_top.y/2},
                {position.x + collision_box.right_bottom.x/2, position.y + collision_box.right_bottom.y/2}
            }
            rendering.draw_circle{only_in_alt_mode=true, width = 1, color = {r = 0, g = 1, b = 0}, surface = player.surface, radius = 0.5, filled = false, target = {x=position.x, y=position.y}, time_to_live = 12000}

            -- Check each tile in the entity's footprint for water
            for x = math.floor(check_area[1][1]), math.ceil(check_area[2][1]) do
                for y = math.floor(check_area[1][2]), math.ceil(check_area[2][2]) do
                    local tile = player.surface.get_tile(x, y)
                    if is_water_tile(tile.name) then
                        error("\"Cannot place " .. entity .. " at " .. position.x .. ", " .. position.y ..
                              " as entity footprint overlaps water. Please try a different location\"")
                    end
                end
            end
        end
        utils.avoid_entity(player_index, entity, position, direction)
        -- Use surface based validation equivalent to LuaPlayer.can_place_entity
        local can_build = utils.can_place_entity(player, entity, position, entity_direction)

        if not can_build then
            if not exact then
                local new_position
                local new_position = nil
                local found_position = false
                -- special logic for orienting offshore pumps correctly.
                if entity == 'offshore-pump' then
                    local pos_dir = find_offshore_pump_position(player, position)
                    if pos_dir then
                        -- Factorio 2.0: direction is already in 16-direction format, no division needed
                        entity_direction = utils.get_entity_direction(entity, pos_dir['direction'])
                        new_position = pos_dir['position']
                        found_position = true
                    end
                else
                    -- Existing search logic for nearby valid position
                    local radius = 1
                    local max_radius = 10

                    while not found_position and radius <= max_radius do
                        for dx = -radius, radius do
                            for dy = -radius, radius do
                                if dx == -radius or dx == radius or dy == -radius or dy == radius then
                                    new_position = {x = position.x + dx, y = position.y + dy}
                                    utils.avoid_entity(player_index, entity, position, direction)
                                    can_build = utils.can_place_entity(player, entity, new_position, entity_direction)
                                    if can_build then
                                        found_position = true
                                        break
                                    end
                                end
                            end
                            if found_position then break end
                        end
                        radius = radius + 1
                    end
                end

                if found_position then
                    local have_built = player.surface.create_entity{
                        name = entity,
                        force = player.force,
                        position = new_position,
                        direction = entity_direction,
                    }
                    if have_built then
                        player.remove_item{name = entity, count = 1}
                        -- game.print("Placed " .. entity .. " at " .. new_position.x .. ", " .. new_position.y)
                        return actions.get_entity(player_index, entity, new_position.x, new_position.y)
                    end
                else
                    error("\"Could not find a suitable position to place " .. entity .. " near the target location.\"")
                end
            else
                -- Clear existing entities if exact placement is required
                local area = {{position.x - 0.25, position.y - 0.25}, {position.x + 0.25, position.y + 0.25}}
                local entities = player.surface.find_entities_filtered{area = area, force = "player"}
                if #entities ~= 0 then
                    -- Build a list of blocking entity names and positions
                    local blocking_info = {}
                    for _, blocking_entity in ipairs(entities) do
                        table.insert(blocking_info, blocking_entity.name .. " at x=" .. blocking_entity.position.x .. " y=" .. blocking_entity.position.y)
                    end
                    local blocking_str = table.concat(blocking_info, ", ")
                    if #entities == 1 then
                        error("\"Could not find a suitable position to place " .. entity .. " at the target location x=" .. position.x .. " y=" .. position.y .. ", as there is an existing object in the way: " .. blocking_str .. "\"")
                    else
                        error("\"Could not find a suitable position to place " .. entity .. " at the target location x=" .. position.x .. " y=" .. position.y .. ", as there are existing objects in the way: " .. blocking_str .. "\"")
                    end
                end
            end

            utils.avoid_entity(player_index, entity, position, direction)

            can_build = utils.can_place_entity(player, entity, position, entity_direction)

            if not can_build then
                local entity_prototype = prototypes.entity[entity]
                local entity_box = entity_prototype.collision_box
                local entity_width = 1
                local entity_height = 1
                if direction == defines.direction.north or direction == defines.direction.south then
                    entity_width = math.abs(entity_box.right_bottom.x - entity_box.left_top.x)
                    entity_height = math.abs(entity_box.right_bottom.y - entity_box.left_top.y)
                else
                    entity_height = math.abs(entity_box.right_bottom.x - entity_box.left_top.x)
                    entity_width = math.abs(entity_box.right_bottom.y - entity_box.left_top.y)
                end

                rendering.draw_rectangle{
                    only_in_alt_mode=true,
                    surface = player.surface,
                    left_top = {position.x - entity_width / 2, position.y - entity_height / 2},
                    right_bottom = {position.x + entity_width / 2, position.y + entity_height / 2},
                    filled = false,
                    color = {r=1, g=0, b=0, a=0.5},
                    time_to_live = 60000
                }

                -- Find what's blocking placement for a better error message
                local blocking_area = {
                    {position.x - entity_width / 2, position.y - entity_height / 2},
                    {position.x + entity_width / 2, position.y + entity_height / 2}
                }
                local blocking_entities = player.surface.find_entities_filtered{area = blocking_area}
                local blocking_info = {}
                for _, blocking_entity in ipairs(blocking_entities) do
                    if blocking_entity.name ~= "character" then
                        table.insert(blocking_info, blocking_entity.name .. " at x=" .. blocking_entity.position.x .. " y=" .. blocking_entity.position.y)
                    end
                end

                -- Check for water tiles
                local has_water = false
                for check_x = math.floor(blocking_area[1][1]), math.ceil(blocking_area[2][1]) do
                    for check_y = math.floor(blocking_area[1][2]), math.ceil(blocking_area[2][2]) do
                        local tile = player.surface.get_tile(check_x, check_y)
                        if tile.name == "water" or tile.name == "deepwater" or tile.name == "water-green" or tile.name == "deepwater-green" or tile.name == "water-shallow" or tile.name == "water-mud" then
                            has_water = true
                            break
                        end
                    end
                    if has_water then break end
                end

                local error_msg = "\"Cannot place " .. entity .. " at x=" .. position.x .. " y=" .. position.y
                if #blocking_info > 0 then
                    error_msg = error_msg .. " - blocked by: " .. table.concat(blocking_info, ", ")
                end
                if has_water then
                    error_msg = error_msg .. " - terrain includes water"
                end
                if #blocking_info == 0 and not has_water then
                    error_msg = error_msg .. " - something is in the way or terrain is unplaceable"
                end
                error_msg = error_msg .. "\""
                error(error_msg)
            end
        end

        local have_built = player.surface.create_entity{
            name = entity,
            force = player.force,
            position = position,
            direction = entity_direction,
        }

        if have_built then
            player.remove_item{name = entity, count = 1}
            -- game.print("Placed " .. entity .. " at " .. position.x .. ", " .. position.y)

            -- Find and return the placed entity
            -- Use the entity prototype's tile dimensions for search area
            local prototype = prototypes.entity[entity]
            local width = 1
            local height = 1
            if prototype and prototype.tile_width then
                width = prototype.tile_width / 2 + 0.5
                height = prototype.tile_height / 2 + 0.5
            end
            local target_area = {
                {position.x - width, position.y - height},
                {position.x + width, position.y + height}
            }
            local entities = player.surface.find_entities_filtered{area = target_area, name = entity}

            if #entities > 0 then
                return utils.serialize_entity(entities[1])
            end
            error("\"Could not find placed entity\"")
        else
            -- create_entity returned nil - collect diagnostic information
            local diag = {}
            diag.entity_name = entity
            diag.position = {x = position.x, y = position.y}
            diag.direction = entity_direction
            diag.can_place = player.surface.can_place_entity{name = entity, position = position, force = player.force, direction = entity_direction}

            -- Check for blocking entities
            local prototype = prototypes.entity[entity]
            local width = 1
            local height = 1
            if prototype and prototype.tile_width then
                width = prototype.tile_width / 2 + 0.5
                height = prototype.tile_height / 2 + 0.5
            end
            local area = {{position.x - width, position.y - height}, {position.x + width, position.y + height}}
            local blocking = player.surface.find_entities_filtered{area = area}
            local blocking_names = {}
            for _, b in ipairs(blocking) do
                if b.name ~= "character" then
                    table.insert(blocking_names, b.name .. " at (" .. b.position.x .. "," .. b.position.y .. ")")
                end
            end
            diag.blocking_entities = blocking_names

            -- Check terrain
            local tile = player.surface.get_tile(position.x, position.y)
            diag.tile_name = tile.name

            local error_msg = string.format(
                "\"create_entity returned nil for %s at (%s, %s). Diagnostics: can_place=%s, tile=%s, blocking=%s\"",
                entity,
                position.x,
                position.y,
                tostring(diag.can_place),
                diag.tile_name,
                #blocking_names > 0 and table.concat(blocking_names, ", ") or "none"
            )
            error(error_msg)
        end
    end

    -- Main execution flow
    validate_distance()
    validate_entity()
    validate_inventory()
    utils.avoid_entity(player_index, entity, position)

    -- Choose placement method based on storage.fast setting
    if storage.fast then
        return fast_place()
    else
        local result = slow_place()
        return result
    end
end
end

-- ==== action: place_entity_next_to ====
do
local function is_large_entity(entity)
    if not entity then return false end
    
    -- Check by size (3x3 or larger)
    local prototype = prototypes.entity[entity.name]
    if prototype then
        local collision_box = prototype.collision_box
        local width = math.abs(collision_box.right_bottom.x - collision_box.left_top.x)
        local height = math.abs(collision_box.right_bottom.y - collision_box.left_top.y)
        return width >= 2.6 and height >= 2.6  -- 3x3 entities have collision box ~2.8x2.8
    end
    
    return false
end

local function get_reserved_positions_around_entity(entity)
    if not is_large_entity(entity) then
        return {}
    end
    
    local pos = entity.position
    local reserved = {}
    
    -- For 3x3 entities, we need positions outside the collision box
    -- The collision box extends ±1.5 from center, so we need at least ±2 to be clear
    local middle_adjacent = {
        {x = pos.x, y = pos.y - 2, side = "north"},      -- North (middle)
        {x = pos.x + 2, y = pos.y, side = "east"},       -- East (middle)
        {x = pos.x, y = pos.y + 2, side = "south"},      -- South (middle)
        {x = pos.x - 2, y = pos.y, side = "west"}        -- West (middle)
    }
    
    for _, reserved_pos in pairs(middle_adjacent) do
        table.insert(reserved, reserved_pos)
    end
    
    return reserved
end


local function find_alternative_position_smart(ref_position, ref_entity, entity_to_place, original_direction, gap)
    local alternatives = {}
    
    -- If placing an inserter near a large entity, try the reserved middle positions first
    if ref_entity and is_large_entity(ref_entity) and (entity_to_place == "inserter" or entity_to_place:find("inserter")) then
        local reserved_positions = get_reserved_positions_around_entity(ref_entity)
        
        for _, reserved_pos in pairs(reserved_positions) do
            -- Calculate what direction this would be from the reference entity
            local dx = reserved_pos.x - ref_entity.position.x
            local dy = reserved_pos.y - ref_entity.position.y
            
            local alt_direction
            if math.abs(dx) > math.abs(dy) then
                alt_direction = dx > 0 and 1 or 3  -- East or West
            else
                alt_direction = dy > 0 and 2 or 0  -- South or North
            end
            
            table.insert(alternatives, {
                position = reserved_pos,
                direction = alt_direction,
                score = 75,  -- High priority for reserved positions
                reason = "Reserved position for large entity"
            })
        end
    end
    
    -- Try directions in order of preference
    local direction_priority = {original_direction}  -- Start with requested direction
    
    -- Add other directions
    for dir = 0, 3 do
        if dir ~= original_direction then
            table.insert(direction_priority, dir)
        end
    end
    
    -- Add standard adjacent positions with different directions
    for _, direction in pairs(direction_priority) do
        for distance = 1, 3 do  -- Try increasing distances
            local offset_x, offset_y = 0, 0
            
            if direction == 0 then     -- North
                offset_y = -distance
            elseif direction == 1 then -- East
                offset_x = distance
            elseif direction == 2 then -- South
                offset_y = distance
            else                       -- West
                offset_x = -distance
            end
            
            local alt_pos = {
                x = ref_position.x + offset_x,
                y = ref_position.y + offset_y
            }
            
            local score = 30 - (distance * 5)  -- Prefer closer positions
            
            table.insert(alternatives, {
                position = alt_pos,
                direction = direction,
                score = score,
                reason = "Alternative position at distance " .. distance
            })
        end
    end
    
    -- Sort by score (highest first)
    table.sort(alternatives, function(a, b) return a.score > b.score end)
    
    return alternatives
end

local function validate_mining_drill_placement(surface, position, entity_name)
    -- Check if the entity is a mining drill
    local prototype = prototypes.entity[entity_name]
    if prototype.type ~= "mining-drill" then
        return true
    end

    -- Get the mining area
    local mining_area = prototype.collision_box
    local area = {
        {position.x + mining_area.left_top.x, position.y + mining_area.left_top.y},
        {position.x + mining_area.right_bottom.x, position.y + mining_area.right_bottom.y}
    }

    -- Check for resources in the mining area
    local resources = surface.find_entities_filtered({
        area = area,
        type = "resource"
    })

    -- For mining drills, we need at least one valid resource
    return #resources > 0
end


actions.place_entity_next_to = function(player_index, entity, ref_x, ref_y, direction, gap)
    -- Ensure we have a valid character, recreating if necessary
    local player = utils.ensure_valid_character(player_index)
    local ref_position = {x = ref_x, y = ref_y}

    local function table_contains(tbl, element)
        for _, value in ipairs(tbl) do
            if value == element then
                return true
            end
        end
        return false
    end

    -- Factorio 2.0 uses 16-direction system: 0 (north), 4 (east), 8 (south), 12 (west)
    local valid_directions = {0, 4, 8, 12}

    if not table_contains(valid_directions, direction) then
        error("Invalid direction " .. direction .. " provided. Please use 0 (north), 4 (east), 8 (south), or 12 (west).")
    end

    -- Convert from Factorio 2.0 direction (0,4,8,12) to internal direction (0,1,2,3) for calculations
    local internal_direction = direction / 4

    local ref_entities = player.surface.find_entities_filtered({
        area = {{ref_x - 0.5, ref_y - 0.5}, {ref_x + 0.5, ref_y + 0.5}},
        type = {"character", "resource"}, -- Find players
        invert = true
    })
    local ref_entity = #ref_entities > 0 and ref_entities[1] or nil

    local function is_transport_belt(entity_name)
        return entity_name == "transport-belt" or
               entity_name == "fast-transport-belt" or
               entity_name == "express-transport-belt"
    end


    local function calculate_position(direction, ref_pos, ref_entity, gap, is_belt, entity_to_place)
        local new_pos = {x = ref_pos.x, y = ref_pos.y}
        local effective_gap = gap or 0

        -- Get reference entity's width/height based on its rotation
        local ref_width, ref_height
        if ref_entity then
            if ref_entity.type == "inserter" then
                ref_width, ref_height = 1, 1
            else
                local ref_orientation = ref_entity.direction
                -- Factorio 2.0: East=4, West=12
                if ref_orientation == defines.direction.east or ref_orientation == defines.direction.west then  -- East or West
                    ref_width = ref_entity.prototype.tile_height
                    ref_height = ref_entity.prototype.tile_width
                else  -- North or South
                    ref_width = ref_entity.prototype.tile_width
                    ref_height = ref_entity.prototype.tile_height
                end
            end
        else
            ref_width = 1
            ref_height = 1
        end

        -- Check if the entity to place is an inserter
        local entity_prototype = prototypes.entity[entity_to_place]
        -- Original spacing calculation for non-inserters
        local entity_width, entity_height
        if direction == 1 or direction == 3 then  -- East or West
            entity_width = entity_prototype.tile_height
            entity_height = entity_prototype.tile_width
        else  -- North or South
            entity_width = entity_prototype.tile_width
            entity_height = entity_prototype.tile_height
        end

        if direction == 0 then     -- North
            new_pos.y = new_pos.y - (math.ceil(ref_height + entity_height)/2 + effective_gap)
        elseif direction == 1 then -- East
            new_pos.x = new_pos.x + (math.ceil(ref_width + entity_width)/2 + effective_gap)
        elseif direction == 2 then -- South
            new_pos.y = new_pos.y + (math.ceil(ref_height + entity_height)/2 + effective_gap)
        else  -- West
            new_pos.x = new_pos.x - (math.ceil(ref_width + entity_width)/2 + effective_gap)
        end

        -- Round the position to the nearest 0.5 to align with Factorio's grid
        new_pos.x = math.ceil(new_pos.x * 2) / 2
        new_pos.y = math.ceil(new_pos.y * 2) / 2

        return new_pos
    end

    local function calculate_position_old(direction, ref_pos, ref_entity, gap, is_belt, entity_to_place)
        local new_pos = {x = ref_pos.x, y = ref_pos.y}
        local effective_gap = gap or 0

        -- Get reference entity's width/height based on its rotation
        local ref_width, ref_height
        if ref_entity then
            local ref_orientation = ref_entity.direction  -- Factorio 2.0: 0,4,8,12 = N,E,S,W
            if ref_orientation == defines.direction.east or ref_orientation == defines.direction.west then  -- East or West
                ref_width = ref_entity.prototype.tile_height
                ref_height = ref_entity.prototype.tile_width
            else  -- North or South
                ref_width = ref_entity.prototype.tile_width
                ref_height = ref_entity.prototype.tile_height
            end
        else
            ref_width = 1
            ref_height = 1
        end

        -- Get entity to place width/height based on desired direction
        local entity_prototype = prototypes.entity[entity_to_place]
        local entity_width, entity_height
        if direction == 1 or direction == 3 then  -- East or West
            entity_width = entity_prototype.tile_height
            entity_height = entity_prototype.tile_width
        else  -- North or South
            entity_width = entity_prototype.tile_width
            entity_height = entity_prototype.tile_height
        end

        -- Calculate spacing based on the relevant dimensions
        if direction == 0 then     -- North
            new_pos.y = new_pos.y - (math.ceil(ref_height + entity_height)/2 + effective_gap)
        elseif direction == 1 then -- East
            new_pos.x = new_pos.x + (math.ceil(ref_width + entity_width)/2 + effective_gap)
        elseif direction == 2 then -- South
            new_pos.y = new_pos.y + (math.ceil(ref_height + entity_height)/2 + effective_gap)
        else  -- West
            new_pos.x = new_pos.x - (math.ceil(ref_width + entity_width)/2 + effective_gap)
        end

        -- Round the position to the nearest 0.5 to align with Factorio's grid
        new_pos.x = math.ceil(new_pos.x * 2) / 2
        new_pos.y = math.ceil(new_pos.y * 2) / 2

        return new_pos
    end

    local is_belt = is_transport_belt(entity)

    local new_position = calculate_position(internal_direction, ref_position, ref_entity, gap, is_belt, entity)
    
    -- Helper function to clear item-on-ground entities at a position
    local function clear_items_on_ground(position, radius)
        local items = player.surface.find_entities_filtered{
            position = position,
            radius = radius or 0.5,
            name = "item-on-ground"
        }
        for _, item in ipairs(items) do
            item.destroy()
        end
    end
    
    -- Clear any item-on-ground entities at the target position before collision check
    clear_items_on_ground(new_position)

    local function player_collision(player, target_area)
        local character_box = {
            left_top = {x = -0.2, y = -0.2},
            right_bottom = {x = 0.2, y = 0.2}
        }
        local character_area = {
            {player.position.x + character_box.left_top.x, player.position.y + character_box.left_top.y},
            {player.position.x + character_box.right_bottom.x, player.position.y + character_box.right_bottom.y}
        }
        return (character_area[1][1] < target_area[2][1] and character_area[2][1] > target_area[1][1]) and
               (character_area[1][2] < target_area[2][2] and character_area[2][2] > target_area[1][2])
    end

    local nearby_entities = player.surface.find_entities_filtered({
        position = new_position,
        radius = 0.5,
        force = player.force
    })

    -- Smart collision resolution with alternative positioning
    if #nearby_entities > 0 then
        local colliding_entity_names = {}
        local has_pole_collision = false
        
        for _, nearby_entity in pairs(nearby_entities) do
            if nearby_entity.name ~= 'laser-beam' and nearby_entity.name ~= "character" then
                table.insert(colliding_entity_names, nearby_entity.name)
                if nearby_entity.type == "electric-pole" then
                    has_pole_collision = true
                end
            end
        end
        
        if #colliding_entity_names > 0 then
            -- Try to find alternative positions, especially for inserters and common factory entities
            local should_try_alternatives = (
                entity == "inserter" or entity:find("inserter") or
                entity == "wooden-chest" or entity == "iron-chest" or entity == "steel-chest" or
                is_transport_belt(entity) or
                has_pole_collision  -- Always try alternatives when blocked by poles
            )
            
            if should_try_alternatives then
                -- Pass internal_direction (0-3) to find_alternative_position_smart
                local alternatives = find_alternative_position_smart(ref_position, ref_entity, entity, internal_direction, gap)

                for i, alternative in pairs(alternatives) do
                    local alt_pos = alternative.position
                    -- Round to grid
                    alt_pos.x = math.ceil(alt_pos.x * 2) / 2
                    alt_pos.y = math.ceil(alt_pos.y * 2) / 2

                    -- Clear items at alternative position before checking if it's clear
                    clear_items_on_ground(alt_pos)

                    -- Convert internal direction (0-3) to Factorio 2.0 direction (0,4,8,12)
                    local alt_factorio_direction = alternative.direction * 4

                    -- Use proper collision detection instead of radius search
                    local alt_clear = player.surface.can_place_entity({
                        name = entity,
                        position = alt_pos,
                        direction = utils.get_entity_direction(entity, alt_factorio_direction),
                        force = player.force
                    })

                    if alt_clear then
                        -- Found a good alternative position!
                        new_position = alt_pos
                        -- Update both internal and Factorio directions
                        internal_direction = alternative.direction
                        direction = alt_factorio_direction

                        -- Update orientation for the new direction
                        orientation = utils.get_entity_direction(entity, direction)
                        
                        
                        goto alternative_found
                    end
                end
            end
            
            -- If no alternatives worked, give the original error with suggestions
            local colliding_entity_name
            if #colliding_entity_names == 1 then
                colliding_entity_name = colliding_entity_names[1]
            elseif #colliding_entity_names == 2 then
                colliding_entity_name = table.concat(colliding_entity_names, " and ")
            else
                colliding_entity_name = table.concat(colliding_entity_names, ", ", 1, #colliding_entity_names - 1) .. ", and " .. colliding_entity_names[#colliding_entity_names]
            end
            
            local suggestions = ""
            if ref_entity and is_large_entity(ref_entity) then
                suggestions = " For large entities like " .. ref_entity.type .. ", consider using the middle sides (N/S/E/W) for inserters and chests, and corners for poles."
            elseif has_pole_collision then
                suggestions = " Consider using connect_entities to place poles in better positions, or manually place the pole elsewhere first."
            end
            
            error("\"A " .. colliding_entity_name .. " already exists at the new position " .. serpent.line(new_position) .. ". Consider increasing the spacing (".. gap.."), changing the direction or changing the reference position (" .. serpent.line(ref_position) .. ")." .. suggestions .. "\"")
        end
    end
    
    ::alternative_found::

    orientation = utils.get_entity_direction(entity, direction)

    if ref_entity then
        local prototype = prototypes.entity[ref_entity.name]
        local collision_box = prototype.collision_box
        local width = math.abs(collision_box.right_bottom.x - collision_box.left_top.x)
        local height = math.abs(collision_box.right_bottom.y - collision_box.left_top.y)

        local target_area = {
            {new_position.x - width / 2, new_position.y - height / 2},
            {new_position.x + width / 2, new_position.y + height / 2}
        }
        while player_collision(player, target_area) do
            player.teleport({player.position.x + width + 1, player.position.y})
        end
    end

    -- Check for player collision and move player if necessary
    local entity_prototype = prototypes.entity[entity]
    local entity_box = entity_prototype.collision_box
    local entity_width = 1
    local entity_height = 1
    if orientation == defines.direction.north or orientation == defines.direction.south then
        entity_width = math.abs(entity_box.right_bottom.x - entity_box.left_top.x)
        entity_height = math.abs(entity_box.right_bottom.y - entity_box.left_top.y)
    else
        entity_height = math.abs(entity_box.right_bottom.x - entity_box.left_top.x)
        entity_width = math.abs(entity_box.right_bottom.y - entity_box.left_top.y)
    end


    local target_area = {
        {new_position.x - entity_width / 2, new_position.y - entity_height / 2},
        {new_position.x + entity_width / 2, new_position.y + entity_height / 2}
    }

    if player_collision(player, target_area) then
        local move_distance = math.max(entity_width, entity_height) + 1
        local move_direction = {x = 0, y = 0}

        if internal_direction == 0 or internal_direction == 2 then -- North or South
            move_direction.x = 1 -- Move East
        else -- East or West
            move_direction.y = 1 -- Move South
        end

        local new_player_position = {
            x = player.position.x + move_direction.x * move_distance,
            y = player.position.y + move_direction.y * move_distance
        }
        player.teleport(new_player_position)
    end

    local area = {{new_position.x - entity_width / 2, new_position.y - entity_height / 2}, {new_position.x + entity_width / 2, new_position.y + entity_height / 2}}

    -- Show bounding box for debugging
    rendering.draw_rectangle({
        only_in_alt_mode=true,
        color = {r = 0, g = 1, b = 0},
        filled = false,
        left_top = area[1],
        right_bottom = area[2],
        surface = player.surface,
        time_to_live = 60000
    })
    rendering.draw_circle({
        only_in_alt_mode=true,
        color = {r = 1, g = 0, b = 0},
        radius = 0.2,
        filled = true,
        target = new_position,
        surface = player.surface,
        time_to_live = 60000
    })
    rendering.draw_circle({
        only_in_alt_mode=true,
        color = {r = 0, g = 0, b = 1},
        radius = 0.2,
        filled = true,
        target = ref_position,
        surface = player.surface,
        time_to_live = 60000
    })

    utils.avoid_entity(player_index, entity, new_position, direction)

    local can_build = player.surface.can_place_entity({
        name = entity,
        position = new_position,
        direction = orientation,
        force = player.force
    })
    if can_build then
        can_build = validate_mining_drill_placement(player.surface, new_position, entity)
        if not can_build then
            error("Cannot place mining drill - no resources found in mining area")
        end
    else
        local entities = player.surface.find_entities_filtered{area = area, type = {"beam", "resource", "player", "character"}, invert=true}
        local blocker_names = {}
        for _, e in ipairs(entities) do
            table.insert(blocker_names, e.type.."("..serpent.line(e.position)..")")
        end
        -- game.print(serpent.line(blocker_names))

        local tree = player.surface.find_entities_filtered{area = area, type = {"tree"}}
        for _, e in ipairs(tree) do
            table.insert(blocker_names, e.name.."("..serpent.line(e.position)..")")
        end
        
        local tiles = player.surface.find_tiles_filtered{area = area, name={"water", "deepwater", "water-green", "deepwater-green", "water-shallow", "water-mud"}}
        if #tiles > 0 then
            for _, e in ipairs(tiles) do
                -- if e.name is not in blocker_names, we should add item
                if not table_contains(blocker_names, e.name.."("..serpent.line(e.position)..")") then
                    table.insert(blocker_names, e.name.."("..serpent.line(e.position)..")")
                end
            end
        end
        -- game.print(serpent.line(blocker_names))

        error("\'Cannot place entity at the position " .. serpent.line(new_position) .. " with the current direction" ..
              ". Attempting to place next to - "..ref_entity.name..". There might be a collision with existing entities or this area cannot be placed on (water). Nearby entities that might be blocking the placement - " .. serpent.line(blocker_names) ..
                ". Consider increasing the spacing (".. gap.."), changing the direction or changing the reference position (" .. serpent.line(ref_position) .. ")\'")

    end

    local new_entity = player.surface.create_entity({
        name = entity,
        position = new_position,
        force = player.force,
        direction = orientation,
        move_stuck_players = true,
    })

    if not new_entity then
        error("Failed to create entity " .. entity .. " at position " .. serpent.line(new_position))
    end

    local placement_info = utils.serialize_entity(new_entity)
    
    local item_stack = {name = entity, count = 1}
    if player.get_main_inventory().can_insert(item_stack) then
        player.get_main_inventory().remove(item_stack)
        return placement_info
    else
        local inv_contents = utils.format_inventory_for_error(player)
        error("Not enough " .. entity .. " in inventory. Current inventory: " .. inv_contents)
    end
end

end

