do
-- move_to

-- Register the tick handler when the module is loaded
script.on_nth_tick(5, function(event)
    if not storage.walking_queues or not next(storage.walking_queues) then return end
    local ok, err = pcall(actions.update_walking_queues)
    if not ok then log("fle-bridge walking-queue error: " .. tostring(err)) end
end)

--local function get_direction(from_pos, to_pos)
