-- ==== action: insert_item ====
do
-- Function to check if an item is a module
local function is_module(item_name)
    local item_proto = prototypes.item[item_name]
    return item_proto and item_proto.type == "module"
end

-- Function to get inventory fullness information
local function get_inventory_info(entity)
    if entity.get_inventory then
        -- Try common inventory types (Factorio 2.0: unified crafter_input for furnaces/assemblers)
        local inv = entity.get_inventory(defines.inventory.chest) or          -- For chests
                   entity.get_inventory(defines.inventory.crafter_input)      -- For furnaces, assemblers, rocket silos

        if inv then
            -- Get actual item count and inventory capacity
            local item_count = 0
            for i = 1, #inv do
                local stack = inv[i]
                if stack and stack.valid_for_read then
                    item_count = item_count + stack.count
                end
            end

            -- Calculate total capacity (slots * stack size)
            local capacity = #inv * prototypes.item[inv[1].name or "iron-plate"].stack_size

            return string.format("(%d/%d items)", item_count, capacity)
        end
    end
    return ""
end

actions.insert_item = function(player_index, insert_item, count, x, y, target_name)
    -- Ensure we have a valid character, recreating if necessary
    local player = utils.ensure_valid_character(player_index)
    local position = {x=x, y=y}
    local surface = player.surface

    -- Check if player has enough items
    local item_count = player.get_item_count(insert_item)
    if item_count == 0 then
        error('\"No '..insert_item..' to insert from your inventory\"')
    end

    local closest_distance = math.huge
    local closest_entity = nil
    local area = {{position.x - 1, position.y - 1}, {position.x + 1, position.y + 1}}
    local buildings = nil

    if target_name then
        buildings = surface.find_entities_filtered{area = area, name=target_name}
    else
        buildings = surface.find_entities_filtered{area = area}
    end

    -- Function to get inventory fullness information
    --local function get_inventory_info(entity)
    --    if entity.get_inventory then
    --        local inv = entity.get_inventory(defines.inventory.chest)
    --        if inv then
    --            return string.format("(%d/%d)", #inv, #inv.get_bar())
    --        end
    --    end
    --    return ""
    --end

    -- Function to check if an item can be inserted into an entity
    local function can_insert_item(entity, item_name)
        if entity.type == "transport-belt" then
            -- All items that can be on ground can be on belts
            local item_prototype = prototypes.item[item_name]
            return item_prototype and not item_prototype.has_flag("only-in-cursor")

        elseif entity.type == "lab" then
            -- Check if the item is a science pack
            local item_prototype = prototypes.item[item_name]
            return item_prototype and item_prototype.type == "tool"

        elseif entity.type == "assembling-machine" then
            -- Check if it's a module first
            if is_module(item_name) then
                local module_inv = entity.get_module_inventory()
                return module_inv and not module_inv.is_full()
            end
            local recipe = entity.get_recipe()
            if recipe then
               -- Check if the item is an ingredient or the result of the recipe
                for _, ingredient in pairs(recipe.ingredients) do
                    if ingredient.name == item_name then
                        return true
                    end
                end
                -- Check if the item is the result of the recipe
                for _, product in pairs(recipe.products) do
                    if product.name == item_name then
                        return true
                    end
                end
                return false
            end
        elseif entity.type == "furnace" then
            -- Check if it's a fuel
            if prototypes.item[item_name].fuel_value > 0 then
                return true
            end
            -- Check furnace inventory for incompatible items (Factorio 2.0: crafter_input)
            local inventory = entity.get_inventory(defines.inventory.crafter_input)
            if inventory and not inventory.is_empty() then
                local existing_item = nil
                for i = 1, #inventory do
                    local stack = inventory[i]
                    if stack.valid_for_read then
                        existing_item = stack.name
                        break
                    end
                end
                if existing_item and existing_item ~= item_name then
                    error("\"furnace already contains " .. existing_item.." so cannot insert " .. item_name .."\"")
                end
            end
            -- Check if it's a valid ingredient for any furnace recipe
            for _, recipe in pairs(prototypes.recipe) do
                if recipe.category == "smelting" then
                    for _, ingredient in pairs(recipe.ingredients) do
                        if ingredient.name == item_name then
                            return true
                        end
                    end
                end
            end
            return false
            ---- Check if it's a fuel
            --if prototypes.item[item_name].fuel_value > 0 then
            --    return true
            --end
            ---- Check if it's a valid ingredient for any furnace recipe
            --for _, recipe in pairs(prototypes.recipe) do
            --    if recipe.category == "smelting" then
            --        for _, ingredient in pairs(recipe.ingredients) do
            --            if ingredient.name == item_name then
            --                return true
            --            end
            --        end
            --    end
            --end
            --return false
        elseif entity.burner then
            -- Check if it's a fuel
            return prototypes.item[item_name].fuel_value > 0
        elseif entity.type == "container" or entity.type == "logistic-container" then
            return true  -- Containers can accept any item
        elseif entity.type == "beacon" then
            -- Beacons only accept modules
            if is_module(item_name) then
                local module_inv = entity.get_module_inventory()
                return module_inv and not module_inv.is_full()
            end
            return false
        end
        -- Add more entity types as needed
        return true
    end

    -- Find the closest suitable building
    for _, building in ipairs(buildings) do
        if building.name ~= 'character' and can_insert_item(building, insert_item) then
            local distance = ((position.x - building.position.x) ^ 2 + (position.y - building.position.y) ^ 2) ^ 0.5
            if distance < closest_distance then
                closest_distance = distance
                closest_entity = building
            end
        end
    end

    if closest_entity == nil then
        error("\"Could not find a nearby entity that can accept " .. insert_item.."\"")
    end

    -- Throw an error if the entity is too far away from the player
    if closest_distance > 10 then
        error("\"Entity at ("..closest_entity.position.x..", "..closest_entity.position.y..") is too far away from your position of ("..player.position.x..", "..player.position.y.."), move closer.\"")
    end

    -- Function to insert items onto a transport belt - one at a time
    local function insert_on_belt(belt, item_name)
        local line1 = belt.get_transport_line(1)
        local line2 = belt.get_transport_line(2)

        -- Try first line
        if line1.can_insert_at_back() then
            if line1.insert_at_back({name = item_name, count = 1}) then
                return 1
            end
        end

        -- If first line failed, try second line
        if line2.can_insert_at_back() then
            if line2.insert_at_back({name = item_name, count = 1}) then
                return 1
            end
        end

        return 0  -- Could not insert on either line
    end

    -- Determine how many items can be inserted
    local insertable_count = math.min(count, item_count)

   -- Attempt to insert items
    local inserted = 0
    if closest_entity.type == "transport-belt" then
        -- For transport belts, we need to use a different method
        -- game.print("Inserting ".. insertable_count.. " items onto transport belt...")
        inserted = insert_on_belt(closest_entity, insert_item)
    elseif closest_entity.type == "assembling-machine" then
        -- Check if inserting a module
        if is_module(insert_item) then
            local module_inv = closest_entity.get_module_inventory()
            if module_inv then
                inserted = module_inv.insert({name=insert_item, count=insertable_count})
            else
                error("\"Assembling machine does not support modules\"")
            end
        else
            local recipe = closest_entity.get_recipe()
            if recipe then
                local is_product = false
                for _, product in pairs(recipe.products) do
                    if product.name == insert_item then
                        is_product = true
                        break
                    end
                end

                if is_product then
                    -- Insert into output inventory
                    inserted = closest_entity.get_output_inventory().insert({name=insert_item, count=insertable_count})
                else
                    -- Insert into input inventory (Factorio 2.0: crafter_input)
                    inserted = closest_entity.get_inventory(defines.inventory.crafter_input).insert({name=insert_item, count=insertable_count})
                end
            else
                error("No recipe set for the assembling machine.")
            end
        end
    elseif closest_entity.type == "beacon" then
        -- Beacons only accept modules
        if is_module(insert_item) then
            local module_inv = closest_entity.get_module_inventory()
            if module_inv then
                inserted = module_inv.insert({name=insert_item, count=insertable_count})
            else
                error("\"Beacon does not have a module inventory\"")
            end
        else
            error("\"Beacons can only accept modules\"")
        end
    else
        -- For other entities, use the normal insert method
        inserted = closest_entity.insert{name=insert_item, count=insertable_count}
    end

    -- game.print("Inserted " .. inserted .. " items.")
    if inserted > 0 then
        -- Only remove successfully inserted items from player
        player.remove_item{name=insert_item, count=inserted}
        -- game.print("Successfully inserted " .. inserted .. " items.")
        return utils.serialize_entity(closest_entity)
    else
        local inventory_info = get_inventory_info(closest_entity)
        local error_msg = string.format(
            "\"Failed to insert %s into %s (type %s) at position %s. " ..
            "Attempted to insert %d items. %s %s\"",
            insert_item,
            closest_entity.name,
            closest_entity.type,
            serpent.line(closest_entity.position),
            insertable_count,
            inventory_info ~= "" and "Inventory is full " .. inventory_info or "Entity might not accept this item or has no available space.",
            inventory_info
        )
        error(error_msg)
    end
end
end

-- ==== action: extract_item ====
do
-- Helper function to check all possible inventories of an entity
local function get_entity_item_count(entity, item_name)
    local inventory_types = {
        defines.inventory.chest,
        defines.inventory.furnace_source,
        defines.inventory.furnace_result,
        defines.inventory.assembling_machine_input,
        defines.inventory.assembling_machine_output,
        defines.inventory.fuel,
        defines.inventory.burnt_result,
        defines.inventory.reactor_source,
        defines.inventory.reactor_result,
        defines.inventory.lab_input,
        defines.inventory.lab_source,
        defines.inventory.mining_drill_input,
        defines.inventory.item_main,  -- For cargo wagons
        defines.inventory.robot_cargo,
        defines.inventory.robot_repair,
        defines.inventory.car_trunk,
        defines.inventory.car_fuel,
        defines.inventory.roboport_material,
        defines.inventory.roboport_robot,
        defines.inventory.storage_tank,
        defines.inventory.artillery_turret_ammo,
        defines.inventory.turret_ammo,
        defines.inventory.beacon_modules,
        defines.inventory.character_main,
        defines.inventory.character_guns,
        defines.inventory.character_ammo,
        defines.inventory.character_armor,
        defines.inventory.character_vehicle,
        defines.inventory.character_trash
    }

    local total_count = 0
    for _, inv_type in ipairs(inventory_types) do
        local inventory = entity.get_inventory(inv_type)
        if inventory then
            total_count = total_count + entity.get_item_count(item_name)
        end
    end
    return total_count
end

-- Helper function to remove items from any valid inventory
local function remove_items_from_entity(entity, stack)
    local inventory_types = {
        defines.inventory.chest,
        defines.inventory.furnace_source,
        defines.inventory.furnace_result,
        defines.inventory.assembling_machine_input,
        defines.inventory.assembling_machine_output,
        defines.inventory.fuel,
        defines.inventory.burnt_result,
        defines.inventory.reactor_source,
        defines.inventory.reactor_result,
        defines.inventory.lab_input,
        defines.inventory.lab_source,
        defines.inventory.mining_drill_input,
        defines.inventory.item_main,
        defines.inventory.robot_cargo,
        defines.inventory.robot_repair,
        defines.inventory.car_trunk,
        defines.inventory.car_fuel,
        defines.inventory.roboport_material,
        defines.inventory.roboport_robot,
        defines.inventory.storage_tank,
        defines.inventory.artillery_turret_ammo,
        defines.inventory.turret_ammo,
        defines.inventory.beacon_modules,
        defines.inventory.character_main,
        defines.inventory.character_guns,
        defines.inventory.character_ammo,
        defines.inventory.character_armor,
        defines.inventory.character_vehicle,
        defines.inventory.character_trash
    }

    local items_remaining = stack.count
    local total_removed = 0

    for _, inv_type in ipairs(inventory_types) do
        if items_remaining <= 0 then
            break
        end

        local inventory = entity.get_inventory(inv_type)
        if inventory then
            local current_stack = {name = stack.name, count = items_remaining}
            local removed = entity.remove_item(current_stack)
            total_removed = total_removed + removed
            items_remaining = items_remaining - removed
        end
    end

    return total_removed
end

actions.extract_item = function(player_index, extract_item, count, x, y, source_name)
    -- Ensure we have a valid character, recreating if necessary
    local player = utils.ensure_valid_character(player_index)
    local position = {x=x, y=y}
    local surface = player.surface

    -- First validate the request
    if count <= 0 then
        error("\"Invalid count: must be greater than 0\"")
    end

    -- Find all entities in range
    local search_radius = 10
    local area = {{position.x - search_radius, position.y - search_radius},
                  {position.x + search_radius, position.y + search_radius}}
    local buildings = nil

    if source_name ~= nil then
        buildings = surface.find_entities_filtered{
            area = area,
            name = source_name
        }
    else
        buildings = surface.find_entities_filtered{
            area = area
        }
    end

    -- Find the closest building with the item we want
    local closest_distance = math.huge
    local closest_entity = nil
    local found_any_items = false

    for _, building in ipairs(buildings) do
        if building.name ~= 'character' then
            local item_count = get_entity_item_count(building, extract_item)
            if item_count > 0 then
                found_any_items = true
                local distance = ((position.x - building.position.x) ^ 2 +
                                (position.y - building.position.y) ^ 2) ^ 0.5
                if distance < closest_distance then
                    closest_distance = distance
                    closest_entity = building
                end
            end
        end
    end

    -- Error handling in priority order

    if #buildings == 0 then
        error("\"Could not find any entities in range\"")
    end

    if not closest_entity then
        if source_name then
            error("\"Could not find a valid "..source_name.." entity containing " .. extract_item.."\"")
        else
            error("\"Could not find a valid entity containing " .. extract_item .. "\"")
        end
    end

    if closest_distance > search_radius then
        error("\"Entity at ("..closest_entity.position.x..", "..closest_entity.position.y..") is too far away from your position of ("..player.position.x..","..player.position.y.."), move closer.\"")
    end

    if not found_any_items then
        error("\"No " .. extract_item .. " found in any nearby entities\"")
    end

    -- Calculate how many items we can actually extract
    local available_count = get_entity_item_count(closest_entity, extract_item)
    local extract_count = math.min(count, available_count)

    -- Create the stack for extraction
    local stack = {name=extract_item, count=extract_count}

    -- Attempt the extraction
    local number_extracted = remove_items_from_entity(closest_entity, stack)

    if number_extracted > 0 then
        -- Insert items into player inventory
        local inserted = player.insert(stack)

        -- If we couldn't insert all items, put them back in the container
        if inserted < number_extracted then
            stack.count = number_extracted - inserted
            closest_entity.insert(stack)
            number_extracted = inserted
        end

        -- game.print("Extracted " .. number_extracted .. " " .. extract_item)
        return number_extracted
    else
        -- This should rarely happen given our prior checks
        error("\"Failed to extract " .. extract_item .. "\"")
    end
end
end

-- ==== action: craft_item ====
do
actions.craft_item = function(player_index, entity, count)
    -- Ensure we have a valid character, recreating if necessary
    local player = utils.ensure_valid_character(player_index)

    local function calculate_crafting_ticks(recipe, crafts_count)
        -- energy_required is in seconds, multiply by 60 to get standard ticks
        -- storage.elapsed_ticks should always represent standard 60 ticks/second
        local ticks_per_craft = (recipe.energy or 0.5) * 60
        return math.ceil(ticks_per_craft * crafts_count)
    end

    local function check_inventory_space(player, item_name, count)
        -- Get the prototype of the item
        local item_prototype = prototypes.item[item_name]
        if not item_prototype then
            return false, "Invalid item prototype"
        end

        -- Calculate how many slots this would need
        local stack_size = item_prototype.stack_size
        local slots_needed = math.ceil(count / stack_size)

        -- Check if player has enough free inventory slots
        local inventory = player.get_main_inventory()
        if not inventory then
            return false, "Cannot access player inventory"
        end

        -- Count free slots and partially filled slots of the same item
        local available_slots = 0
        for i = 1, #inventory do
            local stack = inventory[i]
            if not stack.valid_for_read then
                -- Empty slot
                available_slots = available_slots + 1
            elseif stack.name == item_name and stack.count < stack_size then
                -- Partially filled slot of the same item
                available_slots = available_slots + 1
            end
        end

        if available_slots < slots_needed then
            return false, "Inventory is full - requires " .. slots_needed .. " slots but only " .. available_slots .. " available"
        end

        return true
    end


    local function get_missing_ingredients(player, recipe, count)
        local missing_ingredients = {}
        local crafts_needed = math.ceil(count / recipe.products[1].amount)
        for _, ingredient in pairs(recipe.ingredients) do
            local count_that_player_has = player.get_item_count(ingredient.name)
            local needed = ingredient.amount * crafts_needed
            if count_that_player_has < needed then
                local difference = needed - count_that_player_has
                missing_ingredients[ingredient.name] = difference
            end
        end
        return missing_ingredients
    end

    local function get_required_technology(recipe_name, force)
        for _, tech in pairs(force.technologies) do
            -- Factorio 2.0: effects are on the technology prototype
            local effects = tech.prototype and tech.prototype.effects
            if effects then
                for _, effect in pairs(effects) do
                    if effect.type == "unlock-recipe" and effect.recipe == recipe_name then
                        return tech.name
                    end
                end
            end
        end
        return nil
    end

    local function can_craft_recipe(player, recipe_name)
        local recipe = player.force.recipes[recipe_name]
        if not recipe then
            return false, "recipe for " .. recipe_name .. " doesn't exist, it is a raw resource that must be gathered first"
        end
        if not recipe.enabled then
            local required_tech = get_required_technology(recipe_name, player.force)
            local tech_message = required_tech and string.format(" (requires %s technology)", required_tech) or ""
            return false, "recipe for " .. recipe_name .. " is not unlocked yet" .. tech_message .. ". You need to research the technology first"
        end
        -- Factorio 2.0: Check if the recipe category is one the character can craft
        -- Note: 'player' here is actually the character entity (returned by ensure_valid_character)
        local can_hand_craft = false
        local proto = player.prototype
        if proto then
            local cats = proto.crafting_categories
            if cats then
                can_hand_craft = cats[recipe.category] or false
            else
                -- Character prototype exists but has no crafting_categories
                -- Fallback: allow "crafting" category only
                can_hand_craft = (recipe.category == "crafting")
            end
        else
            -- No prototype - fallback
            can_hand_craft = (recipe.category == "crafting")
        end
        if not can_hand_craft then
            return false, "Item " .. recipe_name .. " cannot be crafted (category: " .. tostring(recipe.category) .. "). Recipe requires a crafting machine or smelting in a furnace"
        end
        return true, recipe
    end

    local function update_production_stats(force, recipe, crafts_count)
        -- Factorio 2.0: production_statistics is now a method requiring surface parameter
        local surface = game.surfaces[1]
        local stats = force.get_item_production_statistics(surface)
        local craft_stats = {crafted_count = crafts_count, inputs = {}, outputs = {}}
        for _, ingredient in pairs(recipe.ingredients) do
            craft_stats.inputs[ingredient.name] = ingredient.amount * crafts_count
            stats.on_flow(ingredient.name, -ingredient.amount * crafts_count)
        end
        for _, product in pairs(recipe.products) do
            if product.type == "item" then
                stats.on_flow(product.name, product.amount * crafts_count)
                craft_stats.outputs[product.name] = product.amount * crafts_count
            end
        end
        table.insert(storage.crafted_items, craft_stats)
    end

    -- Single recursive crafting function that handles both fast and slow modes
    local function attempt_craft(player, entity_name, count, attempted_recipes)
        attempted_recipes = attempted_recipes or {}

        -- Prevent infinite recursion
        if attempted_recipes[entity_name] then
            return 0, "recursive crafting loop detected"
        end
        attempted_recipes[entity_name] = true

        local can_craft, recipe_or_error = can_craft_recipe(player, entity_name)
        if not can_craft then
            return 0, recipe_or_error
        end

        local recipe = recipe_or_error
        local crafts_needed = math.ceil(count / recipe.products[1].amount)
        local actual_craft_count = crafts_needed * recipe.products[1].amount

        -- Check for missing ingredients
        local missing_ingredients = get_missing_ingredients(player, recipe, actual_craft_count)
        if next(missing_ingredients) then
            -- Try to craft each missing ingredient
            for ingredient_name, needed_amount in pairs(missing_ingredients) do
                local crafted_amount, error_msg = attempt_craft(player, ingredient_name, needed_amount, attempted_recipes)
                if crafted_amount == 0 then
                    return 0, "couldn't craft a required sub-ingredient for ".. entity_name .. " - " .. ingredient_name .. " - " .. error_msg .. ". Required " ..ingredient_name.. " amount for " .. entity_name .. " - " .. needed_amount .. ")"
                end
            end
        end

        -- Calculate total ticks needed for this craft
        local crafting_ticks = calculate_crafting_ticks(recipe, crafts_needed)


        -- After potentially crafting intermediates, check if we can now craft the original item
        if storage.fast then
            -- Only add ticks in fast mode since in slow mode they are added naturally
            storage.elapsed_ticks = storage.elapsed_ticks + crafting_ticks

            -- Add inventory space check here
            local can_insert, error_msg = check_inventory_space(player, entity_name, actual_craft_count)
            if not can_insert then
                return 0, error_msg
            end

            -- Fast crafting implementation
            local missing = get_missing_ingredients(player, recipe, actual_craft_count)
            if next(missing) then
                local missing_str = ""
                for name, amount in pairs(missing) do
                    missing_str = missing_str .. name .. " x" .. amount .. ", "
                end
                return 0, "still missing ingredients - " .. missing_str:sub(1, -3)
            end

            for _, ingredient in pairs(recipe.ingredients) do
                player.remove_item({name = ingredient.name, count = ingredient.amount * crafts_needed})
            end

            local crafted = player.insert({name = entity_name, count = actual_craft_count})
            if crafted < actual_craft_count then
                player.surface.spill_item_stack(player.position, {name = entity_name, count = actual_craft_count - crafted})
            end

            update_production_stats(player.force, recipe, crafted)
            return crafted, nil
        else
            -- Slow crafting implementation
            local crafted = player.begin_crafting{count=count, recipe=entity_name}
            if crafted == 0 then
                return 0, "unable to begin crafting - check prerequisites and inventory space"
            end
            update_production_stats(player.force, recipe, crafted)
            return crafted, nil
        end
    end

    -- Main crafting logic
    local total_crafted = 0
    local final_error = nil

    while total_crafted < count do
        local remaining = count - total_crafted
        local crafted_amount, error_msg = attempt_craft(player, entity, remaining, {})

        if crafted_amount > 0 then
            total_crafted = total_crafted + crafted_amount
            if not storage.fast then
                break
            end
        else
            final_error = error_msg
            break
        end
    end

    if total_crafted >= count or (not storage.fast and total_crafted > 0) then
        return count
    elseif total_crafted > 0 then
        error(string.format("\"Successfully crafted %dx but failed to craft %dx %s because %s\"",
            total_crafted, count - total_crafted, entity, final_error))
    else
        error(string.format("\"Failed to craft %dx %s because %s\"",
            count, entity, final_error))
    end
end

end

-- ==== action: pickup_entity ====
do
actions.pickup_entity = function(player_index, x, y, entity)
    -- Ensure we have a valid character, recreating if necessary
    local player = utils.ensure_valid_character(player_index)
    local position = {x=x, y=y}
    local surface = player.surface
    local success = false
    rendering.draw_circle{only_in_alt_mode=true, width = 0.5, color = {r = 0, g = 1, b = 0}, surface = player.surface, radius = 0.25, filled = false, target = position, time_to_live = 12000}

    -- Debug print
    -- game.print("Starting pickup attempt for " .. entity .. " at (" .. x .. ", " .. y .. ")")

    -- Function to check if player can receive items
    local function can_receive_items(items_to_check)
        local main_inventory = player.get_main_inventory()
        -- Check each item individually
        for _, item in pairs(items_to_check) do
            if not main_inventory.can_insert({name = item.name, count = item.count}) then
                return false
            end
        end
        return true
    end

    -- Function to pick up and add entity to player's inventory
    local function pickup_placed_entity(entities)
        for _, ent in pairs(entities) do
            if ent.valid and ent.name == entity then
                -- game.print("Found valid placed entity: " .. ent.name)

                -- Collect all items that need to be inserted
                local items_to_insert = {}

                -- Add entity products
                --local products = ent.prototype.mineable_properties.products
                --if products ~= nil then
                --    for _, product in pairs(products) do
                --        table.insert(items_to_insert, {name=product.name, count=product.amount})
                --    end
                --end

                -- Add chest contents if applicable
                if ent.get_inventory(defines.inventory.chest) then
                    local chest_contents = utils.get_contents_compat(ent.get_inventory(defines.inventory.chest))
                    for name, count in pairs(chest_contents) do
                        table.insert(items_to_insert, {name=name, count=count})
                    end
                end

                -- Add transport belt contents if applicable
                if ent.type == "transport-belt" then
                    -- Check line 1
                    local line1 = ent.get_transport_line(1)
                    local contents1 = utils.get_contents_compat(line1)
                    for name, count in pairs(contents1) do
                        table.insert(items_to_insert, {name=name, count=count})
                    end

                    -- Check line 2
                    local line2 = ent.get_transport_line(2)
                    local contents2 = utils.get_contents_compat(line2)
                    for name, count in pairs(contents2) do
                        table.insert(items_to_insert, {name=name, count=count})
                    end
                end

                -- Add the entity itself
                table.insert(items_to_insert, {name=ent.name, count=1})

                -- Check if player can receive all items
                if not can_receive_items(items_to_insert) then
                    error("Inventory is full")
                end

                -- Insert all items
                for _, item in pairs(items_to_insert) do
                    player.insert(item)
                end

                if ent.can_be_destroyed() then
                    -- game.print("Picked up placed "..ent.name)
                    pcall(ent.destroy{raise_destroy=false, do_cliff_correction=false})
                    return true
                end
            end
        end
        return false
    end

    -- Function to pick up items on ground
    local function pickup_ground_item(ground_items)
        for _, item in pairs(ground_items) do
            if item.valid and item.stack and item.stack.name == entity then
                -- game.print("Found valid ground item: " .. item.stack.name)
                local count = item.stack.count

                -- Check if player can receive the item
                if not can_receive_items({{name=entity, count=count}}) then
                    error("Cannot pick up " .. entity .. " - inventory is full")
                end

                local inserted = player.insert{name=entity, count=count}
                if inserted > 0 then
                    -- game.print("Picked up ground item2 " .. count .. " " .. entity)
                    pcall(item.destroy{raise_destroy=false})
                    return true
                end
            end
            return true
        end
        return false
    end

    -- Find both types of entities first
    local player_entities = surface.find_entities_filtered{
        name=entity,
        position=position,
        radius=0.707,
        force="player"
    }
    -- game.print("Found " .. #player_entities .. " placed entities")

    local ground_items = surface.find_entities_filtered{
        name="item-on-ground",
        position=position,
        radius=0.707
    }
    -- game.print("Found " .. #ground_items .. " ground items")

    -- Try to pick up placed entities first, if any exist
    if #player_entities > 0 then
        success = pickup_placed_entity(player_entities)
        if success then
            -- game.print("Successfully picked up placed entity")
            return {}
        end
    end

    -- Only try ground items if we haven't succeeded with placed entities
    if not success and #ground_items > 0 then
        success = pickup_ground_item(ground_items)
        if success then
            -- game.print("Successfully picked up ground item")
            return {}
        end
    end

    if not success then
        if #player_entities == 0 and #ground_items == 0 then
            error("Couldn't find "..entity.." at position ("..x..", "..y..") to pick up.")
        else
            error("Could not pick up "..entity)
        end
    end

    return {}
end
end

-- ==== action: rotate_entity ====
do
actions.rotate_entity = function(player_index, x, y, direction, entity)
    local character = storage.agent_characters[player_index]
    local lua_player = game.players[player_index]  -- Get the actual LuaPlayer object
    local position = {x=x, y=y}
    local surface = character.surface

    local function table_contains(tbl, element)
        for _, value in ipairs(tbl) do
            if value == element then
                return true
            end
        end
        return false
    end

    local closest_distance = math.huge
    local closest_entity = nil
    local area = {{position.x - 0.5, position.y - 0.5}, {position.x + 0.5, position.y + 0.5}}
    local buildings = surface.find_entities_filtered{area = area, force = "player", name=entity}

    -- Find the closest building (skip rotatable check for assemblers, handled below)
    for _, building in ipairs(buildings) do
        if building.name ~= 'character' then
            local distance = ((position.x - building.position.x) ^ 2 + (position.y - building.position.y) ^ 2) ^ 0.5
            if distance < closest_distance then
                closest_distance = distance
                closest_entity = building
            end
        end
    end

    if closest_entity == nil then
        error("No entity to rotate at the given coordinates.")
    end

    -- Factorio 2.0 uses 16-direction system: 0 (north), 4 (east), 8 (south), 12 (west)
    local valid_directions = {0, 4, 8, 12}

    if not table_contains(valid_directions, direction) then
        error("Invalid direction " .. direction .. " provided. Please use 0 (north), 4 (east), 8 (south), or 12 (west).")
    end

    local target_direction = utils.get_entity_direction(closest_entity.name, direction)

    -- For assembling machines in Factorio 2.0, rotation is complex due to fluid_boxes_off_when_no_fluid_recipe
    -- Without the fle-compat mod, assemblers without a fluid recipe cannot be rotated via .rotate(),
    -- and assemblers with a fluid recipe use .rotate() which rotates both entity and fluid boxes.
    -- We always use destroy/recreate for assemblers to handle both cases reliably.
    if closest_entity.type == "assembling-machine" then
        local current = closest_entity.direction
        local target = target_direction

        if current ~= target then
            -- Save entity state
            local saved_name = closest_entity.name
            local saved_position = closest_entity.position
            local saved_recipe = closest_entity.get_recipe()
            local saved_recipe_name = saved_recipe and saved_recipe.name or nil
            local saved_health = closest_entity.health
            local saved_force = closest_entity.force

            -- Save inventory contents
            local saved_inputs = {}
            local saved_outputs = {}
            local saved_modules = {}

            local input_inv = closest_entity.get_inventory(defines.inventory.assembling_machine_input)
            if input_inv then
                for i = 1, #input_inv do
                    local stack = input_inv[i]
                    if stack and stack.valid_for_read then
                        table.insert(saved_inputs, {name = stack.name, count = stack.count})
                    end
                end
            end

            local output_inv = closest_entity.get_inventory(defines.inventory.assembling_machine_output)
            if output_inv then
                for i = 1, #output_inv do
                    local stack = output_inv[i]
                    if stack and stack.valid_for_read then
                        table.insert(saved_outputs, {name = stack.name, count = stack.count})
                    end
                end
            end

            local modules_inv = closest_entity.get_inventory(defines.inventory.assembling_machine_modules)
            if modules_inv then
                for i = 1, #modules_inv do
                    local stack = modules_inv[i]
                    if stack and stack.valid_for_read then
                        table.insert(saved_modules, {name = stack.name, count = stack.count})
                    end
                end
            end

            -- Destroy the entity
            closest_entity.destroy()

            -- Create new entity with target direction
            local new_entity = surface.create_entity{
                name = saved_name,
                position = saved_position,
                direction = target,
                force = saved_force,
                create_build_effect_smoke = false
            }

            if new_entity then
                -- Set the health
                new_entity.health = saved_health

                -- Set recipe (Factorio 2.0: set_recipe takes recipe, quality - not direction)
                if saved_recipe_name then
                    new_entity.set_recipe(saved_recipe_name)
                    -- Factorio 2.0: set_recipe may change the entity direction for fluid box alignment
                    -- Force the direction back to our target after setting recipe
                    if new_entity.direction ~= target then
                        new_entity.direction = target
                    end
                end

                -- Restore inventories
                local new_input_inv = new_entity.get_inventory(defines.inventory.assembling_machine_input)
                if new_input_inv then
                    for _, item in pairs(saved_inputs) do
                        new_input_inv.insert(item)
                    end
                end

                local new_output_inv = new_entity.get_inventory(defines.inventory.assembling_machine_output)
                if new_output_inv then
                    for _, item in pairs(saved_outputs) do
                        new_output_inv.insert(item)
                    end
                end

                local new_modules_inv = new_entity.get_inventory(defines.inventory.assembling_machine_modules)
                if new_modules_inv then
                    for _, item in pairs(saved_modules) do
                        new_modules_inv.insert(item)
                    end
                end

                closest_entity = new_entity
            end
        end
    else
        -- For other entities, try direct assignment first (works for most entities)
        closest_entity.direction = target_direction

        -- If direction didn't change, try using the rotate() method
        if closest_entity.direction ~= target_direction then
            local current = closest_entity.direction
            local target = target_direction
            local rotations_needed = ((target - current + 16) % 16) / 4

            for i = 1, rotations_needed do
                if closest_entity.rotate then
                    closest_entity.rotate()
                end
            end
        end
    end

    -- Ensure the entity is properly aligned to the grid
    local entity_position = closest_entity.position
    local aligned_position = {
        x = math.floor(entity_position.x),
        y = math.floor(entity_position.y)
    }

    if entity_position.x ~= aligned_position.x or entity_position.y ~= aligned_position.y then
        closest_entity.teleport(aligned_position)
    end

    local serialized = utils.serialize_entity(closest_entity)
    return serialized
end
end

-- ==== action: connect_entities ====
do
-- connect_entities

local MAX_SERIALIZATION_ITERATIONS = 1000  -- Maximum iterations for serializing belt groups
local MAX_PLACEMENT_ATTEMPTS = 50  -- Maximum attempts to find placeable positions
local MAX_PATH_LENGTH = 1000  -- Maximum number of path points to process
local MAX_STRAIGHT_SECTIONS = 100
local MAX_UNDERGROUND_SEGMENTS = 50

-- Wire reach values for different electric pole types
local wire_reach = {
    ['small-electric-pole'] = 4,
    ['medium-electric-pole'] = 9,
    ['big-electric-pole'] = 30,
